MultiLanguageSpellData['mx'][65] = {name = "Celeridad", additional_info = "Instante\n[q]Aumenta tu celeridad cuerpo a cuerpo 20 p. durante 30 s."}
MultiLanguageSpellData['mx'][66] = {name = "Invisibilidad", additional_info = "3% del maná base\n{Instante} {5 min de reutilización}\n[q]Vuelve invisible al taumaturgo durante 3 s, lo que reduce la amenaza cada segundo. Mientras estás invisible, los enemigos no te pueden seleccionar como objetivo. Dura 20 s. [ Glifo de Invisibilidad : Te mueves un 40% más rápido mientras permaneces invisible ]\n El efecto se anulará si realizas cualquier tipo de acción."}
MultiLanguageSpellData['mx'][71] = {name = "Actitud defensiva", additional_info = "{Instante} {1.5 seg de reutilización}\n[q]Actitud de combate para la función de tanque.\n\n Reduce un 25% el daño recibido.\n Aumenta considerablemente la generación de amenaza.\n Genera 1 p. de ira cada 3 s mientras estás en combate."}
MultiLanguageSpellData['mx'][75] = {name = "Disparo automático", additional_info = "Alcance de 40 m\nInstante\nRequiere Arma a distancia\n[q]Dispara automáticamente al objetivo hasta que se cancela."}
MultiLanguageSpellData['mx'][77] = {name = "Caparazón de tortuga", additional_info = nil}
MultiLanguageSpellData['mx'][78] = {name = "Golpe heroico", additional_info = "{30 p. de ira} {Alcance de ataques cuerpo a cuerpo}\n{Hechizo instantáneo} {1.5 seg de reutilización}\nRequiere Arma cuerpo a cuerpo\n[q]Un ataque que inflige al instante un 110 % de daño con arma más 499 p. [un ( 110 * 1.40)% más ( 499 * 1.40) p. si se tiene equipada un arma de una mano] [ Glifo de Golpes mermadores : y reduce la velocidad de movimiento del objetivo un 50% durante 8 s ].\n\n Úsalo cuando tengas más ira de la que puedas gastar."}
MultiLanguageSpellData['mx'][81] = {name = "Esquivar", additional_info = "[q]Da la posibilidad de esquivar los ataques cuerpo a cuerpo del enemigo."}
MultiLanguageSpellData['mx'][87] = {name = "Automation Mechanic Immunity", additional_info = "Instante\n[q]Makes you immune to all spell mechanics. Used in Automation scripts to give the bot immunity to negative effects while still being able to interact with objects."}
MultiLanguageSpellData['mx'][89] = {name = "Entorpecer", additional_info = "Alcance de 30 m\n{Instante} {30 seg de reutilización}\n[q]Inutiliza al enemigo, lo que reduce la velocidad de movimiento un 40 %. Aumenta el tiempo entre ataques cuerpo a cuerpo y a distancia un 26 %. Dura 20 s."}
MultiLanguageSpellData['mx'][91] = {name = "Asalto cruel", additional_info = "Siguiente cuerpo a cuerpo"}
MultiLanguageSpellData['mx'][96] = {name = "Desmembramiento", additional_info = "Alcance de ataques cuerpo a cuerpo\nSiguiente cuerpo a cuerpo\n[q]Aumenta 100 p. el daño infligido en tu próximo golpe cuerpo a cuerpo y hace sangrar al objetivo."}
MultiLanguageSpellData['mx'][99] = {name = "Rugido desorientador", additional_info = "[q0]Talento\n{Instante} {30 seg de reutilización}\n[q]Invoca al espíritu de Ursoc, que ruge y desorienta a todos los enemigos en un radio de 10 m durante 3 s. Cualquier daño infligido eliminará el efecto. Se puede usar en todas las formas."}
MultiLanguageSpellData['mx'][100] = {name = "Cargar", additional_info = "Alcance de 8 - 25 m\n{Instante} {20 seg de reutilización}\n[q]Furia ( Hotfix Passive )\n Carga contra un enemigo y lo aturde durante 1.50 s . Genera 20 p. de ira.\n\n Armas, Protección\n Carga contra un enemigo y lo [ Belisario : enraíza / aturde] [ Glifo de Ataque relámpago : a él y a 2 objetivos cercanos adicionales ]durante [ Belisario : 4 s, y reduce un 50% su velocidad de movimiento durante 15 s / 1.50 s]. Genera 20 p. de ira."}
MultiLanguageSpellData['mx'][101] = {name = "Tropiezo", additional_info = "{15 p. de energía} {Alcance de ataques cuerpo a cuerpo}\n{Instante} {5 seg de reutilización}\n[q]Hace tropezar al enemigo humanoide infligiendo 10 p. de daño y derribándolo durante 3 s. Otorga 1 p. de combo."}
MultiLanguageSpellData['mx'][107] = {name = "Bloqueo", additional_info = "Requiere Escudo\n[q]Da la posibilidad de bloquear al enemigo en ataque cuerpo a cuerpo o a distancia."}
