MultiLanguageSpellData['mx'][116] = {name = "Descarga de Escarcha", additional_info = "{4% del maná base} {Alcance de 40 m}\nHechizo de 2 seg\n[q]Lanza una descarga de Escarcha al enemigo que inflige 1 p. de daño de Escarcha y reduce su velocidad de movimiento un 50 % durante 15 s."}
MultiLanguageSpellData['mx'][118] = {name = "Polimorfia", additional_info = "{2% del maná base} {Alcance de 30 m}\nHechizo de 1.7 seg\n[q]Transforma al enemigo en [ Glifo del pingüino : pingüino ] [ Glifo del mono : mono ] [ Glifo del puercoespín : puercoespín ] [ Glifo de Osezno : cachorro de oso polar / oveja ], lo que lo obliga a deambular durante 50 s.\n\n Mientras deambula, [ Glifo del pingüino : el pingüino ] [ Glifo del mono : el mono ] [ Glifo del puercoespín : el puercoespín ] [ Glifo de Osezno : el cachorro de oso polar / la oveja ] no puede atacar ni lanzar hechizos, pero se regenera muy rápido. Si recibe daño volverá a su forma normal.\n\n Solo se puede aplicar Polimorfia a 1 objetivo al mismo tiempo. Solo funciona con bestias, humanoides y alimañas."}
MultiLanguageSpellData['mx'][120] = {name = "Cono de frío", additional_info = "4% del maná base\n{Instante} {10 seg de reutilización}\n[q]Los objetivos situados en un cono frente al taumaturgo reciben 1 p. de daño de Escarcha y se ralentizan un 60 % durante 6 s."}
MultiLanguageSpellData['mx'][122] = {name = "Nova de Escarcha", additional_info = "2% del maná base\n{Instante} {25 seg de reutilización}\n[q]Golpea a los enemigos situados en un radio de 12 m del taumaturgo, lo que inflige 552 p. de daño de Escarcha y los congela durante un máximo de 8 s. Cualquier daño infligido puede interrumpir su efecto."}
MultiLanguageSpellData['mx'][124] = {name = "Granada de mano de la resistencia Sagrada", additional_info = "Alcance de 30 m\n{Instante} {5 seg de reutilización}\n[q]Bendice a todos los objetivos con una infusión Sagrada de poder o los maldice con el azote de todos los asaltantes."}
MultiLanguageSpellData['mx'][126] = {name = "Ojo de Kilrogg", additional_info = "{4% del maná base} {Rango ilimitado}\nHechizo de 2 seg\n[q]Invoca un Ojo de Kilrogg y vincula tu visión a él. El ojo [ Glifo de Ojo de Kilrogg : se mueve con rapidez / entra en sigilo y se mueve con rapidez], pero es muy frágil. [ Glifo de Ojo de Kilrogg : Si lanzas Círculo demoníaco: invocar mientras controlas un Ojo de Kilrogg, el círculo aparecerá en la ubicación del ojo ]"}
MultiLanguageSpellData['mx'][130] = {name = "Caída lenta", additional_info = "{1% del maná base} {Alcance de 40 m}\nInstante\n[q]Disminuye la velocidad de caída de un objetivo amistoso del grupo o banda durante 30 s."}
