MultiLanguageSpellData['mx'][339] = {name = "Raíces enredadoras", additional_info = "{6.5% del maná base} {Alcance de 35 m}\nHechizo de 1.7 seg\n[q]Enraíza al objetivo en el sitio durante 30 s. El daño infligido puede interrumpir el efecto. [ Encarnación : Árbol de vida: Lanzamiento instantáneo ]"}
