MultiLanguageSpellData['mx'][518] = {name = "Invocar gusano", additional_info = "Rango ilimitado\nInstante\n[q]Invoca un engendro de Fankriss de las profundidades de Ahn'Qiraj."}
MultiLanguageSpellData['mx'][527] = {name = "Purificar", additional_info = "{2.6% del maná base} {Alcance de 40 m}\n{Instante} {8 seg de reutilización}\n[q]Disipa los efectos dañinos del objetivo, lo que elimina todos los efectos mágicos y de enfermedades."}
MultiLanguageSpellData['mx'][528] = {name = "Disipar magia", additional_info = "{2.6% del maná base} {Alcance de 30 m}\nInstante\n[q]Elimina 1 efecto mágico beneficioso del objetivo enemigo."}
