MultiLanguageSpellData['mx'][546] = {name = "Caminar sobre el agua", additional_info = "{3.5% del maná base} {Alcance de 30 m}\nInstante\n[q]Permite a un objetivo amistoso caminar sobre el agua durante 10 min. Cualquier daño infligido con posterioridad anulará su efecto."}
MultiLanguageSpellData['mx'][550] = {name = "Anular veneno", additional_info = "{100 p. de maná} {Alcance de 30 m}\nInstante\n[q]El objetivo es inmune al veneno durante 30 s y se cura de todos los venenos."}
MultiLanguageSpellData['mx'][556] = {name = "Regreso astral", additional_info = "5.9% del maná baseHechizo de 10 seg 15 min de reutilización\n[q]El Vacío Abisal absorbe al taumaturgo y lo devuelve a [ Glifo de Fijación astral : l Santuario de la Tierra de tu facción / <Hearthstone Location>. Habla con un tabernero en otro sitio para convertirlo en tu nuevo hogar.]"}
MultiLanguageSpellData['mx'][568] = {name = "Ráfaga Arcana", additional_info = "Instante\n[q]Inflige 4050 to 4950 p. de daño Arcano a todos los enemigos que se encuentren en un radio de 10 m, lo que reduce su velocidad de movimiento un 70% y los derriba."}
MultiLanguageSpellData['mx'][578] = {name = "Lobo negro", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un lobo negro que se puede montar."}
MultiLanguageSpellData['mx'][579] = {name = "Lobo rojo", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un lobo rojo que se puede montar."}
MultiLanguageSpellData['mx'][580] = {name = "Lobo gris", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un lobo gris que se puede montar."}
MultiLanguageSpellData['mx'][581] = {name = "Lobo invernal", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un lobo invernal que se puede montar."}
MultiLanguageSpellData['mx'][585] = {name = "Punición", additional_info = "{2.7% del maná base} {Alcance de 30 m}\nHechizo de 1.5 seg\n[q]Pune al enemigo y le inflige 2361 p. de daño Sagrado. [ Glifo de Punición : Si el objetivo está afectado por Fuego Sagrado, el daño aumenta un 20% ] [ Si el objetivo está afectado por Palabra de poder: consuelo, el daño aumenta un 20% ]"}
MultiLanguageSpellData['mx'][586] = {name = "Desvanecerse", additional_info = "3.5% del maná base\n{Instante} {30 seg de reutilización}\n[q]Te desvaneces, lo que elimina temporalmente toda tu amenaza [ Glifo de Desvanecerse : y reduce todo el daño recibido un 10% ] durante 10 s. [ Espectro : Cuando utilizas Desvanecerse, eliminas todos los efectos de reducción de movimiento activos sobre ti, y te mueves sin trabas durante 5 s. ]"}
MultiLanguageSpellData['mx'][588] = {name = "Fuego interno", additional_info = "Instante\n[q]Una ráfaga de energía Sagrada colma al taumaturgo, lo que aumenta un 60 % el valor que los objetos confieren a tu armadura y un 10 % el poder con hechizos. [ Voluntad interna : Solo puedes tener activo Voluntad interna o Fuego interno ]"}
MultiLanguageSpellData['mx'][589] = {name = "Palabra de las Sombras: dolor", additional_info = "{4.4% del maná base} {Alcance de 40 m}\nInstante\n[q]Una palabra de oscuridad que inflige 780 p. de daño de las Sombras al instante y ( 4678 - 780 ) p. de daño de las Sombras extra durante 18 s."}
MultiLanguageSpellData['mx'][596] = {name = "Rezo de sanación", additional_info = "{4.5% del maná base} {Alcance de 40 m}\nHechizo de 2.5 seg\n[q]Un potente rezo sana 8689 p. a los miembros del grupo de un objetivo amistoso en un radio de 30 m."}
MultiLanguageSpellData['mx'][603] = {name = "Fatalidad", additional_info = "60 Furia demoníaca Alcance de 40 m\nHechizo instantáneo\n[q]Aterra al objetivo con fatalidad inminente, lo que inflige 4006 p. de daño de las Sombras durante 1 min.\n\n Cuando Fatalidad asesta un golpe crítico, invoca a un diablillo salvaje para que ataque al objetivo."}
MultiLanguageSpellData['mx'][605] = {name = "Subyugar mente", additional_info = "[q0]Talento\n{2% del maná base} {Alcance de 30 m}\nHechizo de 1.8 seg\n[q]Controla una mente de un nivel máximo de 4 durante 30 s. No funciona contra seres mecánicos."}
MultiLanguageSpellData['mx'][606] = {name = "Putrefacción mental", additional_info = "{240 p. de maná} {Alcance de 30 m}\nHechizo de 2 seg\n[q]Drena 2160 p. de maná del objetivo durante 30 s."}
MultiLanguageSpellData['mx'][611] = {name = "Sello de sacrificio", additional_info = "Hechizo de 3 seg"}
MultiLanguageSpellData['mx'][633] = {name = "Imposición de manos", additional_info = "Alcance de 40 m\n{Instante} {10 min de reutilización}\n[q]Sana a un objetivo amistoso la misma cantidad que tu salud máxima [ Glifo de Divinidad : y hace que recuperes un 10% de tu maná máximo ]. No se puede utilizar sobre un objetivo con Abstinencia. Causa Abstinencia durante 1 min."}
MultiLanguageSpellData['mx'][635] = {name = "Luz Sagrada", additional_info = "{12.6% del maná base} {Alcance de 40 m}\nHechizo de 2.5 seg\n[q]Sana a un objetivo amistoso 8869 p."}
MultiLanguageSpellData['mx'][642] = {name = "Escudo divino", additional_info = "{Instante} {5 min de reutilización}\n[q]Te protege de todo el daño y hechizos durante 8 s, pero reduce todo el daño que inflijas un 50%.\n\n No se puede lanzar sobre un objetivo con Abstinencia. Provoca Abstinencia durante 1 min."}
