MultiLanguageSpellData['mx'][673] = {name = "Armadura menor", additional_info = "Instante\n[q]Aumenta la armadura 50 p. durante 1 h. Elixir guardián."}
MultiLanguageSpellData['mx'][674] = {name = "Doble empuñadura", additional_info = "[q]Permite que las armas de una mano y las armas de mano izquierda se equipen como armas de mano izquierda."}
MultiLanguageSpellData['mx'][676] = {name = "Desarmar", additional_info = "Alcance de ataques cuerpo a cuerpo\n{Instante} {1 min de reutilización}\n[q]Desarma al enemigo de sus armas y escudo durante 8 s. Las criaturas desarmadas infligen mucho menos daño."}
MultiLanguageSpellData['mx'][686] = {name = "Descarga de las Sombras", additional_info = "{40 Furia demoníaca / 5.5% del maná base} {Alcance de 40 m}\nHechizo de 1.7 seg\n[q]Lanza una descarga de sombras al enemigo que le inflige 1 p. de daño de las Sombras."}
MultiLanguageSpellData['mx'][688] = {name = "Invocar diablillo", additional_info = "20% del furia demoníaca base / 20% del maná base\nHechizo de 5 seg\n[q]Invoca a un diablillo a las órdenes del brujo.\n\n Los diablillos pueden lanzar Descarga de Fuego a distancia [ Diablillo: Cauterizar al amo : sanar a su amo en el tiempo ] [ Diablillo: Carbonizar magia : disipar efectos mágicos hostiles ] . [ Quemar alma : Quemar alma:\nLanzamiento instantáneo. ]"}
MultiLanguageSpellData['mx'][689] = {name = "Drenar vida", additional_info = "1% de base maná más 1% por segundo Alcance de 40 m\nCanalizado (Hechizo de 6 seg)\n[q]Drena la vida del objetivo, le inflige ( 357 + 0.334 * Spell power) p. de daño de las Sombras y restaura un 2 % de la salud total del taumaturgo cada 1 s. Dura 6 s. [ Quemar alma : Quemar alma:\nSanación aumentada un ( 3 / 2 * 100 - 100)%. ]"}
MultiLanguageSpellData['mx'][691] = {name = "Invocar manáfago", additional_info = "20% del furia demoníaca base / 25% del maná base\nHechizo de 5 seg\n[q]Invoca a un manáfago a las órdenes del brujo.\n\n A los manáfagos les atrae la magia [ Manáfago: Bloqueo de hechizo : pueden interrumpir el lanzamiento de hechizos ] y se sanan al consumir los efectos mágicos beneficiosos de sus enemigos. [ Quemar alma : Quemar alma:\nLanzamiento instantáneo. ]"}
MultiLanguageSpellData['mx'][697] = {name = "Invocar abisario", additional_info = "20% del furia demoníaca base / 25% del maná base\nHechizo de 5 seg\n[q]Invoca a un abisario a las órdenes del brujo.\n\n Los abisarios pueden soportar potentes ataques [ Abisario: Desarmar : desarmar a los atacantes cuerpo a cuerpo ] [ Abisario: Escudo de las Sombras : infligir daño de las Sombras a los enemigos que los dañan ] [ Abisario: Baluarte de las Sombras : aumentar su salud cuando se encuentran cerca de la muerte ] [ Abisario: Sufrimiento : y provocar a los enemigos que atacan a su amo / . ] [ Quemar alma : Quemar alma:\nLanzamiento instantáneo. ]"}
MultiLanguageSpellData['mx'][698] = {name = "Ritual de invocación", additional_info = "{4% del maná base} {Alcance de 30 m}\nCanalizado (Hechizo de 2 min) 2 min de reutilización\n[q]Da comienzo a un ritual que crea un Portal de invocación. Los aliados pueden usar el Portal de invocación para invocar a un miembro del grupo o banda seleccionado.\n\nRituales\nNecesita al taumaturgo y a 2 aliados más para completarse."}
MultiLanguageSpellData['mx'][700] = {name = "Dormir", additional_info = "{60 p. de maná} {Alcance de 30 m}\nHechizo de 1.5 seg\n[q]Duerme a un objetivo enemigo durante un máximo de 20 s. Cualquier daño despertará al objetivo. Solo se puede dormir a 1 objetivo a la vez. No es fiable en objetivos con nivel superior a 30."}
MultiLanguageSpellData['mx'][703] = {name = "Garrote", additional_info = "{45 p. de energía} {Alcance de ataques cuerpo a cuerpo}\nInstante\nRequiere Sigilo\n[q]Agarrota al enemigo, lo que lo silencia durante 3 s e inflige [( 147 + Attack power * 1 * 0.078) * 6] p. de daño durante 18 s, aumentado por tu poder de ataque. Tienes que estar en modo sigilo. Otorga 1 p. de combo [ Capa y daga : y provoca que aparezcas detrás del objetivo ]."}
MultiLanguageSpellData['mx'][710] = {name = "Desterrar", additional_info = "{30 Furia demoníaca / 3% del maná base} {Alcance de 30 m}\nHechizo de 1.5 seg\n[q]Destierra a un demonio, aberración o elemental enemigo durante un máximo de 30 s.\n\nDesterrado\nEl objetivo no puede hacer nada, pero es invulnerable. Límite de 1 objetivo.\n\n Lanzar Desterrar de nuevo cancelará el hechizo."}
MultiLanguageSpellData['mx'][712] = {name = "Invocar súcubo", additional_info = "20% del furia demoníaca base / 25% del maná base\nHechizo de 5 seg\n[q]Invoca a un súcubo a las órdenes del brujo.\n\n Los súcubos son peligrosos hechiceros de corto alcance. Pueden [ Súcubo: Invisibilidad inferior : volverse invisibles ] [ Súcubo: Anguilazo : repeler a los enemigos ] [ Súcubo: Invisibilidad inferior : y ] seducir a las criaturas humanoides, lo que les impide atacar. [ Quemar alma : Quemar alma:\nLanzamiento instantáneo. ]"}
MultiLanguageSpellData['mx'][713] = {name = "Invocar íncubo", additional_info = "80% del maná base\nHechizo de 6 seg\n[q]Invoca un íncubo bajo las órdenes del brujo. [ Quemar alma : Quemar alma: Lanzamiento instantáneo. ]"}
MultiLanguageSpellData['mx'][720] = {name = "Enredar", additional_info = "Instante\n[q]La guarida de Fankriss el Implacable atrae al objetivo al camino de las proles de silítido cercanas y lo enraíza durante 8 s."}
MultiLanguageSpellData['mx'][724] = {name = "Pozo de Luz", additional_info = "{5.4% del maná base} {Alcance de 40 m}\nHechizo de 0.5 seg 3 min de reutilización\n[q]Crea un Pozo de luz sagrado. Los jugadores aliados pueden hacer clic en el Pozo de luz sagrado para recuperar [(( 5735 + (Spell power * .553))) * 1.5] p. de salud cada 2 s durante 6 s. Los ataques que recibas equivalentes a un 30% de tu salud total cancelarán el efecto. El Pozo de luz sagrado dura 3 min o 15 cargas."}
MultiLanguageSpellData['mx'][731] = {name = "Enredar", additional_info = "Instante\n[q]La guarida de Fankriss el Implacable atrae al objetivo al camino de las proles de silítido cercanas y lo enraíza durante 8 s."}
MultiLanguageSpellData['mx'][740] = {name = "Tranquilidad", additional_info = "27.1% del maná baseCanalizado (Hechizo de 8 seg) 8 min de reutilización\n[q]Sana a los 5 objetivos (12 en estancias de 25 jugadores) del grupo o banda cercanos con menos salud en un radio de 40 m con Tranquilidad cada 2 s durante 8 s.\n\n Tranquilidad sana 9037 p. más 1 p. extra cada 2 s durante 8 s. Se acumula hasta 3 veces. El druida debe canalizar su magia para mantener el hechizo."}
MultiLanguageSpellData['mx'][742] = {name = "Pulverizar", additional_info = "10 min de reutilización\n(Probabilidad de que accione: 35%)"}
MultiLanguageSpellData['mx'][744] = {name = "Veneno", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\n[q]Inflige daño de Naturaleza a un enemigo cada 3 s durante 15 s."}
MultiLanguageSpellData['mx'][745] = {name = "Telaraña", additional_info = "Alcance de 30 m\nInstante\n[q]Lanza una telaraña sobre un enemigo y lo inmoviliza durante 5 s."}
MultiLanguageSpellData['mx'][746] = {name = "Primeros auxilios", additional_info = "Alcance de 15 m\nCanalizado (Hechizo de 6 seg)\n[q]Sana 66 p. de daño durante 6 s."}
MultiLanguageSpellData['mx'][747] = {name = "Invocar imágenes", additional_info = "Instante\n[q]Invoca 2 copias del taumaturgo."}
MultiLanguageSpellData['mx'][750] = {name = "Malla de placas", additional_info = "[q]Te permite equipar armaduras de placas."}
MultiLanguageSpellData['mx'][755] = {name = "Cauce de salud", additional_info = "Alcance de 45 m\nCanalizado (Hechizo de 6 seg)\n[q]Sacrifica un 2 % de tu salud máxima para restaurar un 6 % de la salud máxima de tu demonio invocado cada 1 s. Dura 6 s.\n [\nCanal potenciado\nVolver a lanzar este hechizo antes de que acabe aumenta la duración 0.05 s.\n Se acumula 0 veces. ] [ Quemar alma: Cauce de salud : Quemar alma:\nRestaura un 140% más de salud y reduce el daño recibido un 30 % durante 10 s. ]"}
MultiLanguageSpellData['mx'][759] = {name = "Crear gema de maná", additional_info = "18% del maná base\nHechizo de 3 seg\n[q]Crea una gema de maná que se puede utilizar para [ Glifo de Maná suelto : restaurar 0 p. de maná durante hasta cancelación / restaurar al instante 45000 p. de maná] y contiene hasta 3 cargas.\n\nObjetos creados\nLos objetos creados por arte de magia desaparecen si el jugador permanece desconectado durante más de 15 min."}
MultiLanguageSpellData['mx'][768] = {name = "Forma felina", additional_info = "3.7% del maná base\nInstante\n[q]Cambio a Forma felina, lo que provoca que la agilidad aumente el poder de ataque, que aumente el daño de los ataques automáticos un 100% y la velocidad de movimiento un 25% (se acumula con la mayoría de los aumentos de velocidad). [ Glifo de Forma felina : Además, toda la sanación realizada sobre ti aumenta un 20% ]\n También protege al taumaturgo de los efectos de polimorfia y permite el uso de varias facultades felinas.\n\n La regeneración de energía continúa cuando no estás en forma felina.\n\n El cambio de forma libera al taumaturgo de los efectos de reducción de movimiento."}
MultiLanguageSpellData['mx'][770] = {name = "Fuego feérico", additional_info = "{7.5% del maná base} {Alcance de 35 m}\nInstante\n[q]Unas hadas rodean al objetivo, lo que impide que entre en sigilo o se haga invisible, además de provocar 3 aplicaciones del perjuicio Armadura debilitada.\n\n Inflige 10 p. de daño [ Glifo de Silencio feérico : silencia al objetivo durante 3 s ] y tiene un 25% de probabilidad de reiniciar el tiempo de reutilización de Destrozar cuando se lanza bajo forma de oso.\n\n Armadura debilitada\n Debilita la armadura del objetivo un 4% durante 30 s. Se acumula hasta un máximo de 3 veces."}
MultiLanguageSpellData['mx'][774] = {name = "Rejuvenecimiento", additional_info = "{14.5% del maná base} {Alcance de 40 m}\nInstante\n[q]Sana al objetivo 1 p. y 1 p. extra cada 3 s durante 12 s."}
MultiLanguageSpellData['mx'][779] = {name = "Flagelo", additional_info = "{15 p. de ira} {Alcance de 8 m}\n{Hechizo instantáneo} {3 seg de reutilización}\nRequiere Forma de oso\n[q]Flagela a los enemigos cercanos, lo que inflige 246 p. de daño.\n\n Inflige un 20 % de daño extra a los objetivos que sangran."}
MultiLanguageSpellData['mx'][781] = {name = "Separación", additional_info = "Rango ilimitado\n{Instante} {20 seg de reutilización}\n[q]Intentas saltar hacia atrás [ Inmediatez : lo que elimina los efectos de reducción de movimiento y aumenta tu velocidad de movimiento un 60% durante 8 s ] [ Por los pelos : y se activa una trampa que atrapa a todos los objetivos en un radio de 8 m en telarañas pegajosas, lo que les impide moverse durante 8 s ]. [ Glifo de Liberación : Restaura un 5 % de tu salud máxima ]"}
MultiLanguageSpellData['mx'][783] = {name = "Forma de viaje", additional_info = "5.6% del maná base\nInstante\n[q]Cambio a Forma de viaje, lo que aumenta la velocidad un 40%. También protege al taumaturgo de los efectos de polimorfia. Solo se puede usar en el exterior.\n\n El cambio de forma libera al taumaturgo de los efectos de reducción de movimiento."}
MultiLanguageSpellData['mx'][785] = {name = "Consecución veraz", additional_info = "{260 p. de maná} {Alcance de 45 m}\nHechizo de 0.5 seg\n[q]Transformado por los poderes del profeta Skeram, el objetivo se convierte y se llena de poder divino. Mientras está convertido, los hechizos del objetivo son de lanzamiento instantáneo, el daño aumenta un 300%, todas las resistencias aumentan 50 p. y la velocidad de movimiento aumenta un 40%. Dura 20 s."}
