MultiLanguageSpellData['mx'][974] = {name = "Escudo de tierra", additional_info = "{19% del maná base} {Alcance de 40 m}\nInstante\n[q]Protege al objetivo con un escudo de tierra que aumenta la eficacia de los hechizos de sanación del chamán sobre el objetivo un 20 % y provoca que los ataques sanen al objetivo escudado ( 2043 + Spell power * 0.13) p. 9 cargas. Dura 10 min. Este efecto solo puede tener lugar una vez cada pocos segundos.\n\n Escudo de tierra solo puede utilizarse con un objetivo a la vez y solo puede haber un Escudo elemental activo a la vez sobre ti.\n(3.5s de reutilización)"}
MultiLanguageSpellData['mx'][980] = {name = "Agonía", additional_info = "{1% del maná base} {Alcance de 40 m}\nInstante\n[q]Aflige con una agonía creciente que inflige hasta ( 327 * 10) p. de daño de las Sombras durante 24 s.\n\n El daño se inflige despacio al principio y aumenta progresivamente cada vez que inflige daño."}
MultiLanguageSpellData['mx'][982] = {name = "Revivir mascota", additional_info = "35 p. de enfoque\nHechizo de 4 seg\n[q]Revive tu mascota y la devuelve a la vida con el 100% de su salud de base."}
MultiLanguageSpellData['mx'][1022] = {name = "Mano de protección", additional_info = "{7% del maná base} {Alcance de 40 m}\n{Instante} {5 min de reutilización}\n[q]Da a un miembro del grupo o banda una Mano que lo protege de todos los ataques físicos durante 10 s, pero durante ese tiempo el objetivo no puede atacar ni utilizar facultades físicas. Los jugadores solo pueden tener una Mano activa por paladín a la vez.\n\n No se puede lanzar sobre un objetivo con Abstinencia. Provoca Abstinencia durante 1 min."}
MultiLanguageSpellData['mx'][1038] = {name = "Mano de salvación", additional_info = "{6% del maná base} {Alcance de 40 m}\n{Instante} {2 min de reutilización}\n[q]Da a un miembro del grupo o banda una Mano que elimina toda su amenaza durante 10 s. Los jugadores solo pueden tener una Mano activa por paladín a la vez."}
MultiLanguageSpellData['mx'][1044] = {name = "Mano de libertad", additional_info = "{7% del maná base} {Alcance de 40 m}\n{Instante} {25 seg de reutilización}\n[q]Da a un objetivo amistoso una Mano que le concede inmunidad a los efectos de reducción de movimiento durante 6 s. Los jugadores solo pueden tener una Mano activa por paladín a la vez."}
MultiLanguageSpellData['mx'][1050] = {name = "Sacrificio", additional_info = "Hechizo de 1 seg"}
MultiLanguageSpellData['mx'][1064] = {name = "Sanación en cadena", additional_info = "{22.5% del maná base} {Alcance de 40 m}\nHechizo de 2.5 seg\n[q]Sana 7590 p. a un objetivo aliado y luego salta a los objetivos más heridos para sanarlos. Si se lanza sobre un miembro del grupo o la banda, la sanación continuará aplicándose solo a los otros miembros del grupo. [ Restauración : Fuera de las arenas y los campos de batalla, cada salto reduce un 20 % la efectividad de la sanación ] Sana a un total de 4 objetivos."}
MultiLanguageSpellData['mx'][1066] = {name = "Forma acuática", additional_info = "5.6% del maná base\nInstante\n[q]Cambio a Forma acuática, lo que aumenta la velocidad de nado un 50% y permite al druida respirar bajo el agua. También protege al taumaturgo de los efectos de polimorfia.\n\n El cambio de forma libera al taumaturgo de los efectos de reducción de movimiento."}
MultiLanguageSpellData['mx'][1079] = {name = "Destripar", additional_info = "{30 p. de energía} {Alcance de ataques cuerpo a cuerpo}\nInstante\nRequiere Forma felina\n[q]Remate que inflige daño de sangrado con el tiempo. El daño aumenta por punto de combo:\n\n 1 punto: [floor(((((4 + (Attack power * 0.0484))) * 1) * (( 1 * 1 * 1 * 1 * 1 ))) + 113 ) * 8] p. de daño durante 16 s.\n 2 puntos: [floor(((((4 + (Attack power * 0.0484))) * 2) * (( 1 * 1 * 1 * 1 * 1 ))) + 113 ) * 8] p. de daño durante 16 s.\n 3 puntos: [floor(((((4 + (Attack power * 0.0484))) * 3) * (( 1 * 1 * 1 * 1 * 1 ))) + 113 ) * 8] p. de daño durante 16 s.\n 4 puntos: [floor(((((4 + (Attack power * 0.0484))) * 4) * (( 1 * 1 * 1 * 1 * 1 ))) + 113 ) * 8] p. de daño durante 16 s.\n 5 puntos: [floor(((((4 + (Attack power * 0.0484))) * 5) * (( 1 * 1 * 1 * 1 * 1 ))) + 113 ) * 8] p. de daño durante 16 s.\n\n Cada vez que aplicas Triturar, Devastar o Destrozar sobre tu objetivo mientras estás en Forma felina, la duración de Destripar en el objetivo se extiende 2 s, hasta un máximo de 6 s."}
MultiLanguageSpellData['mx'][1090] = {name = "Dormir", additional_info = "{90 p. de maná} {Alcance de 30 m}\nHechizo de 1.5 seg\n[q]Duerme a un objetivo enemigo durante un máximo de 30 s. Cualquier daño despertará al objetivo. Solo se puede dormir a 1 objetivo a la vez. No es fiable en objetivos con nivel superior a 30."}
MultiLanguageSpellData['mx'][1098] = {name = "Subyugar demonio", additional_info = "{5% del maná base} {Alcance de 30 m}\nHechizo de 3 seg\n[q]Subyuga al demonio objetivo y lo obliga a obedecer tus órdenes. Dura un máximo de 5 min.\n\nSubyugado\nMientras está subyugado, el tiempo entre los ataques del demonio aumenta un 30% y su velocidad de lanzamiento de hechizos se reduce un 20%."}
MultiLanguageSpellData['mx'][1120] = {name = "Drenar alma", additional_info = "1.5% de base maná más 1.5% por segundo Alcance de 40 m\nCanalizado (Hechizo de 12 seg)\n[q]Drena el alma del objetivo, lo que inflige ( 275 + Spell power * 0.257) p. de daño de las Sombras cada 2 s y vigoriza un fragmento de alma después de infligir daño dos veces. Si el objetivo muere y aporta honor o experiencia, se vigorizan 4 fragmentos de alma. Dura 12 s.\n\n Si el objetivo tiene un 20 % de salud o menos cuando Drenar alma inflige daño, inflige un 100 % de daño extra y provoca que el resto de tus efectos de daño periódico de Aflicción inflijan al instante un 60 % de su daño periódico normal."}
MultiLanguageSpellData['mx'][1121] = {name = "Enredar", additional_info = "Alcance de 100 m\nInstante\n[q]La guarida de Fankriss el Implacable atrae al objetivo al camino de las proles de silítido cercanas y lo enraíza durante 8 s."}
MultiLanguageSpellData['mx'][1122] = {name = "Invocar infernal", additional_info = "{25% del maná base} {Alcance de 30 m}\n{Instante} {10 min de reutilización}\n[q]Invoca un meteoro de El Vacío Abisal que inflige 1069 p. de daño de Fuego y aturde a todos los objetivos enemigos en el área de efecto durante 2 s. Del cráter surge un infernal a las órdenes del taumaturgo durante 1 min.\n\n El infernal inflige un gran daño de área de efecto y atacará preferentemente a los objetivos que estén cerca del punto de impacto."}
MultiLanguageSpellData['mx'][1126] = {name = "Marca de lo Salvaje", additional_info = "{5% del maná base} {Alcance de 30 m}\nInstante\n[q]Aumenta la fuerza, la agilidad y el intelecto del objetivo amistoso un 5% durante 1 h.\n\n Si el objetivo está en tu grupo o banda, todos los miembros del grupo o banda se verán afectados."}
MultiLanguageSpellData['mx'][1127] = {name = "Comida", additional_info = "Instante\n[q]Restaura ( 325 * 5) p. de salud durante 25 s. Debes permanecer sentado mientras comes."}
MultiLanguageSpellData['mx'][1129] = {name = "Comida", additional_info = "Instante\n[q]Restaura 1711 p. de salud durante 30 s. Debes permanecer sentado mientras comes."}
MultiLanguageSpellData['mx'][1130] = {name = "Marca del cazador", additional_info = "Alcance de 100 m\nInstante\n[q]Deja la Marca del cazador en el objetivo, lo que aumenta el daño a distancia de todos los que ataquen al objetivo un 5 %. Además, el cazador siempre podrá ver y rastrear al objetivo.\n\n Disparo Arcano, Disparo de quimera, Matar y Disparo explosivo aplican automáticamente Marca del cazador.\n\n Dura 5 min."}
MultiLanguageSpellData['mx'][1131] = {name = "Comida", additional_info = "Instante\n[q]Restaura 2792 p. de salud durante 30 s. Debes permanecer sentado mientras comes."}
