MultiLanguageSpellData['mx'][1329] = {name = "Mutilar", additional_info = "{55 p. de energía} {Alcance de ataques cuerpo a cuerpo}\nInstante\n[q]Ataque instantáneo con ambas armas que inflige un 280 % de daño con arma más 312 p. extra con cada arma. Otorga 2 p. de combo."}
