MultiLanguageSpellData['mx'][1449] = {name = "Deflagración Arcana", additional_info = "3% del maná base\nInstante\n[q]Provoca una explosión de magia Arcana alrededor del taumaturgo, lo que inflige 503 p. de daño Arcano a todos los objetivos en un radio de 10 m. [ Carga Arcana : Reinicia la duración de las cargas Arcanas y tiene un 30 % de probabilidad de generar una carga Arcana si se golpea al menos a un objetivo ]"}
MultiLanguageSpellData['mx'][1454] = {name = "Transfusión de vida", additional_info = "Instante\n[q][ Glifo de Transfusión de vida : Coloca sobre ti un efecto de absorción de sanación igual al 15 % de tu salud total que se acumula durante hasta cancelación y restaura / Restaura] ( 15 * Total health * 0.01) p. de maná. [ Glifo de Transfusión de vida : Dura hasta cancelación ]"}
MultiLanguageSpellData['mx'][1459] = {name = "Luminosidad Arcana", additional_info = "{1% del maná base} {Alcance de 30 m}\nInstante\n[q]Infunde luminosidad al objetivo, lo que aumenta su poder con hechizos un 10% y su probabilidad de golpe crítico un 5% durante 1 h.\n\n Si el objetivo pertenece a tu grupo o banda, todos los miembros del grupo o banda se verán afectados."}
MultiLanguageSpellData['mx'][1462] = {name = "Tradición de bestias", additional_info = "Alcance de 40 m\nInstante\n[q]Reúne información sobre la bestia objetivo. En pantalla verás indicadores de daño, salud, armadura, cualquier resistencia especial y de la dieta. Además, Tradición de bestias te indicará si puedes domar o no a la bestia y qué habilidades tiene cuando está domesticada."}
MultiLanguageSpellData['mx'][1463] = {name = "Resguardo de encantador", additional_info = "[q0]Talento\n{Instante} {25 seg de reutilización}\n[q]Te coloca un resguardo mágico que absorbe hasta ( 1041 + Spell power * 1.0) p. de daño durante 8 s. El daño absorbido restaurará hasta un 18 % de tu maná máximo.\n\n Cuando el efecto se acaba, obtienes hasta un 15% de daño con hechizos aumentado durante 25 s en función de la absorción usada.\n\nPasivo:\n Aumenta un 6% el daño con hechizos y un 65% la regeneración de maná. Este efecto se desactiva mientras Resguardo de encantador está en tiempo de reutilización."}
MultiLanguageSpellData['mx'][1464] = {name = "Embate", additional_info = "{25 p. de ira} {Alcance de ataques cuerpo a cuerpo}\nHechizo instantáneo\nRequiere Arma cuerpo a cuerpo\n[q]Golpea al oponente y le inflige un 275 % de daño de arma y 1246 p. de daño más a ese objetivo. [ Machaque colosal : Inflige un 10 % más de daño a los objetivos afectados por tu Machaque colosal ] [ Golpes de barrido : Mientras Golpes de barrido está activo, un 35 % del daño infligido por Embate también golpeará a todos los demás enemigos en un radio de 2 m ]"}
MultiLanguageSpellData['mx'][1485] = {name = "Metawheel Boulder", additional_info = "Rango ilimitado\nHechizo de 2 seg\n[q]Dispara al objetivo con un arma a distancia."}
MultiLanguageSpellData['mx'][1490] = {name = "Maldición de los Elementos", additional_info = "{4% del maná base} {Alcance de 40 m}\nInstante\n[q]Maldice al objetivo [ Glifo de Maldición de los Elementos : y a 2 objetivos cercanos extra ], lo que aumenta el daño mágico recibido un 5 % durante 5 min.\n\nMaldiciones\nUn brujo solo puede tener una maldición activa por objetivo. [ Quemar alma: Maldición : Quemar alma:\nTu Maldición de los Elementos afectará a todos los enemigos en un radio de 10 m alrededor de tu objetivo. ]"}
MultiLanguageSpellData['mx'][1494] = {name = "Rastrear bestias", additional_info = "Instante\n[q]Muestra la ubicación de todas las bestias cercanas en el minimapa."}
MultiLanguageSpellData['mx'][1499] = {name = "Trampa congelante", additional_info = "{Instante} {30 seg de reutilización}\n[q]Coloca una trampa de Escarcha que congela al primer enemigo que se acerca, lo que impide toda acción durante un máximo de 1 min [ Glifo de Consuelo : y elimina todos los efectos de daño en el tiempo ]. Cualquier daño romperá el hielo [ Glifo de Trampa congelante : y reducirá la velocidad de movimiento de la víctima un 70% durante 4 s ]. [ Glifo de Sin escapatoria : Tu probabilidad de golpe crítico con todas tus facultades a distancia aumenta un 100% contra el objetivo hasta que se rompa el efecto ]Solo puede haber un objetivo congelado al mismo tiempo. La trampa dura 1 min."}
MultiLanguageSpellData['mx'][1509] = {name = "Solo MJ desact.", additional_info = nil}
MultiLanguageSpellData['mx'][1513] = {name = "Asustar bestia", additional_info = "{25 p. de enfoque} {Alcance de 30 m}\nHechizo de 1.5 seg\n[q]Asusta a una bestia haciendo que huya durante un máximo de 20 s. El daño infligido puede interrumpir el efecto. Solo se puede asustar a una bestia cada vez."}
MultiLanguageSpellData['mx'][1515] = {name = "Domesticar bestia", additional_info = "Alcance de 30 m\nCanalizado (Hechizo de 10 seg)\n[q]Da comienzo al proceso de domesticación de una bestia para convertirla en tu mascota. Si por cualquier motivo pierdes la atención de la bestia, el proceso no se completará."}
MultiLanguageSpellData['mx'][1516] = {name = "Disparo presuroso", additional_info = "Alcance de 5 - 30 m\n1 min de reutilización\nRequiere Arma a distancia\n[q]Dispara instantáneamente tu arma, inflige 5 p. de daño extra."}
MultiLanguageSpellData['mx'][1528] = {name = "Liberar al maestro", additional_info = "Alcance de 5 m\nInstante\n[q]Libera a tu maestro de cualquier vínculo."}
MultiLanguageSpellData['mx'][1535] = {name = "Nova de Fuego", additional_info = "{13.7% del maná base} {Alcance de 100 m}\n{Instante} {4 seg de reutilización}\n[q]Incendia tu hechizo Choque de llamas en cualquier enemigo cercano, lo que hace que cada uno de ellos desprenda una ola de llamas que inflige 1 p. de daño de Fuego al resto de enemigos en un radio de 10 m."}
