MultiLanguageSpellData['mx'][1539] = {name = "Alimentar mascota", additional_info = "Rango ilimitado\nInstante\n[q]Alimenta a tu mascota con el objeto seleccionado, lo que restaura un 50% de su salud total. No se puede usar en combate."}
MultiLanguageSpellData['mx'][1543] = {name = "Bengala", additional_info = "Alcance de 40 m\n{Instante} {20 seg de reutilización}\n[q]Saca a la luz a todos los enemigos escondidos o invisibles en un radio de 10 m de la zona seleccionada durante 20 s."}
