MultiLanguageSpellData['mx'][1680] = {name = "Torbellino", additional_info = "30 p. de ira\nHechizo instantáneo\nRequiere Arma cuerpo a cuerpo\n[q]En un torbellino de acero atacas a todos los enemigos en un radio de 8 m [ Sed de sangre : con ambas armas ], e infliges un 85% de daño con arma a cada enemigo."}
MultiLanguageSpellData['mx'][1706] = {name = "Levitar", additional_info = "{0.9% del maná base} {Alcance de 30 m}\nInstante\n[q]Permite levitar al objetivo amistoso del grupo o banda y hace que flote a varios cm del suelo. Mientras levita, el objetivo caerá a una velocidad reducida y podrá caminar sobre el agua. Cualquier daño infligido anulará su efecto. Dura 10 min."}
MultiLanguageSpellData['mx'][1715] = {name = "Seccionar", additional_info = "{10 p. de ira} {Alcance de ataques cuerpo a cuerpo}\n{Hechizo instantáneo} {1 seg de reutilización}\nRequiere Arma cuerpo a cuerpo\n[q]Mutila al enemigo y reduce su velocidad de movimiento un 50% durante 15 s."}
MultiLanguageSpellData['mx'][1719] = {name = "Temeridad", additional_info = "{Instante} {3 min de reutilización}\n[q]Otorga a tus ataques especiales un 30% extra de probabilidad de asestar un golpe crítico. Dura 12 s."}
MultiLanguageSpellData['mx'][1725] = {name = "Distraer", additional_info = "{30 p. de energía} {Alcance de 30 m}\n{Instante} {30 seg de reutilización}\n[q]Lanza una distracción que llama la atención de los monstruos cercanos durante 10 s. No rompe el sigilo."}
MultiLanguageSpellData['mx'][1742] = {name = "Agazapar", additional_info = "{Instante} {45 seg de reutilización}\n[q]Tu mascota se agazapa, lo que reduce un 40% el daño recibido durante 6 s. Al agazaparse, la velocidad de movimiento de tu mascota se reduce un 50%."}
MultiLanguageSpellData['mx'][1752] = {name = "Golpe siniestro", additional_info = "{50 p. de energía} {Alcance de ataques cuerpo a cuerpo}\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Un golpe instantáneo que inflige 280 p. de daño además de un 240 % de tu daño con arma normal. [ Permiso de Golpe siniestro : Otorga 0 p. de combo ]"}
MultiLanguageSpellData['mx'][1766] = {name = "Patada", additional_info = "Alcance de ataques cuerpo a cuerpo\n{Instante} {15 seg de reutilización}\n[q]Una patada rápida que interrumpe el lanzamiento de hechizos y evita que se puedan lanzar hechizos de esa misma escuela durante 5 s. [ Glifo de Patada : Si interrumpes un hechizo con éxito, el tiempo de reutilización de Patada se reduce 6 s ]"}
MultiLanguageSpellData['mx'][1776] = {name = "Gubia", additional_info = "{45 p. de energía} {Alcance de ataques cuerpo a cuerpo}\n{Instante} {10 seg de reutilización}\nRequiere Arma cuerpo a cuerpo\n[q]Hiere los ojos de un objetivo enemigo, lo que lo incapacita durante 4 s. El objetivo debe estar de cara a ti. Cualquier daño infligido provoca que el objetivo se recupere inmediatamente."}
MultiLanguageSpellData['mx'][1784] = {name = "Sigilo", additional_info = "{Instante} {6 seg de reutilización}\n[q]Te oculta entre las sombras, lo que te permite acechar a enemigos sin ser visto. [ Acechador nocturno : La velocidad de movimiento aumenta un 0% cuando estás en modo sigilo ]Dura hasta que se cancela."}
