MultiLanguageSpellData['mx'][1943] = {name = "Ruptura", additional_info = "{25 p. de energía} {Alcance de ataques cuerpo a cuerpo}\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Remate que inflige daño en el tiempo, aumentado por tu poder de ataque. Se prolonga por cada punto de combo:\n 1 p.: [( 231 + 2 * 1 * 1 + 0.025 * Attack power * 1 ) * 0.5 * 8] p. de daño durante 8 s\n 2 p.: [( 231 + 2 * 1 * 2 + 0.04 * Attack power * 1 ) * 0.5 * 12] p. de daño durante 12 s\n 3 p.: [( 231 + 2 * 1 * 3 + 0.05 * Attack power * 1 ) * 0.5 * 16] p. de daño durante 16 s\n 4 p.: [( 231 + 2 * 1 * 4 + 0.056 * Attack power * 1 ) * 0.5 * 20] p. de daño durante 20 s\n 5 p.: [( 231 + 2 * 1 * 5 + 0.062 * Attack power * 1 ) * 0.5 * 24] p. de daño durante 24 s"}
MultiLanguageSpellData['mx'][1949] = {name = "Llamas infernales", additional_info = "2% de base maná más 2% por segundo\nCanalizado (Hechizo de 14 seg)\n[q]Prende el área que rodea al taumaturgo, lo que le inflige 1 p. de daño de Fuego a sí mismo y 224 p. de daño de Fuego a todos los enemigos cercanos cada 1 s. Dura 14 s.\n\n Genera 10 p. de furia demoníaca por segundo más 3 p. de furia demoníaca por segundo en objetivos secundarios."}
