MultiLanguageSpellData['mx'][8017] = {name = "Arma Muerdepiedras", additional_info = "9.4% del maná base\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Imbuye de la furia de la tierra el arma del chamán, lo que aumenta toda la generación de amenaza un 30% y reduce el daño recibido un 5%. Dura 60 min. [ Desatar elementos : Desatar este encantamiento obliga al objetivo enemigo a atacarte durante 5 s ]"}
MultiLanguageSpellData['mx'][8024] = {name = "Arma Lengua de Fuego", additional_info = "7% del maná base\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Imbuye de fuego el arma del chamán, lo que aumenta el daño mágico infligido un 7%. Cada golpe inflige 1 - 1 p. de daño de Fuego extra en función de la velocidad del arma. Las armas más lentas infligen más daño de Fuego por golpe. Dura 60 min. [ Desatar elementos : Desatar este encantamiento inflige 1241 p. de daño de Fuego a un objetivo enemigo y aumenta el daño infligido por el siguiente hechizo de Fuego del chamán un 30 % ]"}
MultiLanguageSpellData['mx'][8033] = {name = "Arma Estigma de Escarcha", additional_info = "7% del maná base\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Imbuye de escarcha el arma del chamán. Cada golpe tiene una probabilidad de infligir 42 p. de daño de Escarcha extra y de reducir la velocidad de movimiento del objetivo un 50 % durante 8 s. Dura 60 min. [ Desatar elementos : Desatar este encantamiento inflige 969 p. de daño de Escarcha a un objetivo enemigo y reduce su velocidad de movimiento un 50 % durante 5 s. Ve aumentada su eficacia si el objetivo ya está afectado por un efecto de Escarcha de reducción de movimiento ]"}
