MultiLanguageSpellData['mx'][14515] = {name = "Subyugar mente", additional_info = "{30 p. de maná} {Alcance de 20 m}\nHechizo de 2 seg\n[q]Controla a un enemigo humanoide hasta el nivel 25 durante 15 s."}
MultiLanguageSpellData['mx'][14516] = {name = "Golpear", additional_info = "Alcance de ataques cuerpo a cuerpo\nSiguiente cuerpo a cuerpo\nRequiere Arma cuerpo a cuerpo\n[q]Golpea a un enemigo e inflige daño cuerpo a cuerpo aumentado."}
MultiLanguageSpellData['mx'][14517] = {name = "Golpe de cruzado", additional_info = "{40 p. de maná} {Alcance de ataques cuerpo a cuerpo}\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Inflige un 60% de daño con arma normal a un enemigo y aumenta el daño Sagrado que recibe 10 p. por Golpe de cruzado. Puede aplicarse hasta 5 veces. Dura 15 s."}
