MultiLanguageSpellData['mx'][14807] = {name = "[q2]Varita mágica superior", additional_info = "Hechizo de 1.5 seg\nHerramientas: Vara rúnica de cobre\nComponentes:\nMadera simple , Esencia mágica superior\n[q]Crea una varita mágica superior.\n[q2]Varita mágica superior\nSe liga al equiparlo\nA distancia Varita\n5 - 11 p. de daño Velocidad 1.80 + 5 - 11 Arcano p. de daño\n(8.89 p. de daño por segundo)\n+2 intelecto\nDurabilidad 55 / 55\nNecesitas ser de nivel 13"}
