MultiLanguageSpellData['mx'][14895] = {name = "Abrumar", additional_info = "Alcance de ataques cuerpo a cuerpo\n{Instante} {5 seg de reutilización}\nRequiere Arma cuerpo a cuerpo\n[q]Armas ( Hotfix Passive )\n Abruma instantáneamente a un enemigo y le inflige daño con arma más 35 p. Solo puede utilizarse después de que el objetivo esquive. El Abrumar no se puede bloquear, ni esquivar ni parar.\n\n Furia, Protección\n Abruma instantáneamente a un enemigo y le inflige daño con arma más 15 p. Solo puede utilizarse después de que el objetivo esquive. El Abrumar no se puede bloquear, ni esquivar ni parar."}
MultiLanguageSpellData['mx'][14897] = {name = "Veneno ralentizante", additional_info = "Alcance de 30 m\nInstante\n[q]Aumenta el tiempo entre los ataques de un enemigo un 25% y ralentiza su velocidad de movimiento un 30% durante 8 s."}
MultiLanguageSpellData['mx'][14900] = {name = "Sanación en cadena", additional_info = "{150 p. de maná} {Alcance de 40 m}\nHechizo de 2.5 seg\n[q]Imbuye a un aliado herido con energía de sanación que se extiende a otro aliado cercano. El hechizo afecta hasta a 3 objetivos, pero la energía de sanación disminuye un 50% en cada objetivo sucesivo."}
