MultiLanguageSpellData['mx'][15292] = {name = "[q3]Pulverizador Hierro Negro", additional_info = "Hechizo de 10 seg\nHerramientas: Martillo de herrero\nComponentes:\nBarra de hierro negro (18), Corazón de fuego (4)\n[q3]Pulverizador Hierro Negro\nSe liga al equiparlo\nDos manos Maza\n140 - 211 p. de daño Velocidad 3.70\n(47.43 p. de daño por segundo)\nDurabilidad 100 / 100\nNecesitas ser de nivel 50\n[q2]Probabilidad al acertar: Aturde al objetivo durante 8 s."}
MultiLanguageSpellData['mx'][15293] = {name = "[q3]Malla Hierro Negro", additional_info = "Hechizo de 3.5 seg\nHerramientas: Martillo de herrero\nComponentes:\nBarra de hierro negro (10), Corazón de fuego (2)\n[q3]Malla Hierro Negro\nSe liga al equiparlo\nPecho Malla\n386 armadura\n+21 agilidad\n+14 aguante\n[q2]Aumenta tu índice de golpe crítico + 14 p.\nDurabilidad 135 / 135\nNecesitas ser de nivel 51"}
