MultiLanguageSpellData['mx'][16195] = {name = "Crear faltriquera de hueso de codillo", additional_info = "Hechizo de 2 seg\nComponentes:\nCharm Pouch (DND) , Magic Knucklebone (DND) (6)\n[q]Coloca 7 huesos de codillo mágicos en la faltriquera de encantamiento para crear una faltriquera de hueso de codillo."}
MultiLanguageSpellData['mx'][16196] = {name = "Resurgimiento", additional_info = "[q]Mientras Escudo de agua está activo, recuperas maná cuando tus hechizos de sanación directa tienen un efecto crítico. Recuperas ( 8849 * 100 / 100) p. de maná con un crítico de Ola de sanación o de Ola de sanación superior, ( 8849 * 0.6 * 100 / 100) p. de maná con un crítico de Oleada de sanación, Mareas vivas o Desatar vida y ( 8849 * 0.333 * 100 / 100) p. de maná con un crítico de Sanación en cadena."}
