MultiLanguageSpellData['mx'][23079] = {name = "[q2]Recombobulador sublime", additional_info = "Hechizo de 3.5 seg\nComponentes:\nTubo de torio (2), Transformador de veraplata , Paño rúnico (2)\n[q2]Recombobulador sublime\nAbalorio\nRequiereIngeniería\n(275)\n[q2]Uso: Restaura 374 p. de salud y maná a un objetivo amistoso e intenta disipar cualquier efecto de polimorfia sobre él. La eficacia es reducida frente a efectos de polimorfia de taumaturgos de nivel 61 y superior. (5 Min Reutilización)\n10 cargas"}
MultiLanguageSpellData['mx'][23080] = {name = "Carga de seforio potente", additional_info = "Hechizo de 5 seg\nComponentes:\nTrasto de torio (2), Pólvora densa (3), Cuero basto (2), Agua de manantial refrescante\nRequiereIngeniería\n(275)\n[q2]Uso: Revienta puertas o cofres bien cerrados."}
MultiLanguageSpellData['mx'][23081] = {name = "[q3]Reflector de llamas hiperradiante", additional_info = "Hechizo de 10 seg\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nBarra de hierro negro (4), Transformador de veraplata (3), Esencia de agua (6), Rubí estrella (4), Diamante de Azeroth (2)\n[q3]Reflector de llamas hiperradiante\nSe liga al equiparlo\nAbalorio\n+18 resistencia a Fuego\nNecesitas ser de nivel 53\nRequiereIngeniería\n(290)\n[q2]Uso: Devuelve los hechizos de Fuego a quien los lanza durante 5 s. Existe la posibilidad de que fracase con jugadores de nivel superior a 60. (5 Min Reutilización)"}
MultiLanguageSpellData['mx'][23082] = {name = "[q3]Reflector de las Sombras ultradeslumbrante", additional_info = "Hechizo de 10 seg\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nBarra de hierro negro (8), Transformador de veraplata (4), Esencia viva (6), Esencia de no-muerto (4), Diamante de Azeroth (2), Ópalo grande (2)\n[q3]Reflector de las Sombras ultradeslumbrante\nSe liga al equiparlo\nAbalorio\n+20 resistencia a Sombras\nNecesitas ser de nivel 55\nRequiereIngeniería\n(300)\n[q2]Uso: Devuelve los hechizos de las Sombras a quien los lanza durante 5 s. Existe la posibilidad de que fracase cuando lo usan jugadores de nivel superior a 60. (5 Min Reutilización)"}
MultiLanguageSpellData['mx'][23096] = {name = "[q2]Roboalarma gnómico", additional_info = "Hechizo de 2 seg\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nBarra de torio (4), Cableado de fusibles\n[q2]Roboalarma gnómico\n(2)\nRequiereIngeniería\n(265)\n[q2]Uso: Invoca a un roboalarma gnómico que escanea la zona en busca de enemigos en sigilo. El roboalarma a veces ofrece señales falsas. Dura hasta 2 min. (5 Min Reutilización)"}
