MultiLanguageSpellData['mx'][27585] = {name = "[q3]Cinturón de obsidiana pesado", additional_info = "Hechizo de 15 seg\nHerramientas: Martillo de herrero\nComponentes:\nFragmento de obsidiana pequeño (14), Barra de torio encantado (4), Esencia de tierra (2)\n[q3]Cinturón de obsidiana pesado\nSe liga al equiparlo\nCintura Placas\n352 armadura\n+25 fuerza\nDurabilidad 45 / 45\nNecesitas ser de nivel 60\n[q2]Equipar: + 6 p. todas las resistencias."}
MultiLanguageSpellData['mx'][27586] = {name = "[q4]Escudo de obsidiana dentado", additional_info = "Hechizo de 15 seg\nHerramientas: Martillo de herrero\nComponentes:\nFragmento de obsidiana grande (8), Fragmento de obsidiana pequeño (24), Barra de torio encantado (8), Esencia de tierra (4)\n[q4]Escudo de obsidiana dentado\nSe liga al equiparlo\nMano izquierda Escudo\n2209 armadura\n[q2]+ 9 de esquivar\nDurabilidad 120 / 120\nNecesitas ser de nivel 60\n[q2]Equipar: + 6 p. todas las resistencias.\n[q2]Equipar: Al recibir un hechizo dañino, el taumaturgo de ese hechizo tiene un 5% de probabilidad de ser silenciado durante 3 s. (Probabilidad de que accione: 5%, 20s de reutilización)"}
MultiLanguageSpellData['mx'][27587] = {name = "[q4]Coraza gruesa de obsidiana", additional_info = "Hechizo de 15 seg\nHerramientas: Martillo de herrero\nComponentes:\nFragmento de obsidiana grande (18), Fragmento de obsidiana pequeño (40), Barra de torio encantado (12), Esencia de tierra (10), Esmeralda enorme (4)\n[q4]Coraza gruesa de obsidiana\nSe liga al equiparlo\nPecho Placas\n796 armadura\n+38 fuerza\n+16 aguante\nDurabilidad 165 / 165\nNecesitas ser de nivel 60\n[q2]Equipar: Al recibir un hechizo de daño tienes el 30% de probabilidad de conseguir un hechizo escudo 6 s que absorbe 300 to 500 de ese tipo de daño. (Probabilidad de que accione: 30%, 10s de reutilización)"}
MultiLanguageSpellData['mx'][27588] = {name = "[q3]Cinturón de obsidiana ligero", additional_info = "Hechizo de 15 seg\nHerramientas: Martillo de herrero\nComponentes:\nFragmento de obsidiana pequeño (14), Cuero encantado (4)\n[q3]Cinturón de obsidiana ligero\nSe liga al equiparlo\nCintura Malla\n238 armadura\n+16 agilidad\n[q2]Aumenta tu índice de golpe crítico + 14 p.\nDurabilidad 45 / 45\nNecesitas ser de nivel 60\n[q2]Equipar: + 6 p. todas las resistencias."}
MultiLanguageSpellData['mx'][27589] = {name = "[q4]Garra negra del Destructor", additional_info = "Hechizo de 10 seg\nHerramientas: Martillo de herrero\nComponentes:\nFragmento de obsidiana grande (8), Fragmento de obsidiana pequeño (24), Cuero encantado (8), Frasco de poder supremo\n[q4]Garra negra del Destructor\nSe liga al equiparlo\nManos Malla\n334 armadura\n+14 agilidad\n[q2]Aumenta tu índice de golpe crítico + 14 p.\nDurabilidad 55 / 55\nNecesitas ser de nivel 60\n[q2]Equipar: En ataques cuerpo a cuerpo o a distancia que alcancen al objetivo, obtienes 10 p. de maná y, si es posible, absorbes 10 p. de maná del objetivo."}
