MultiLanguageSpellData['mx'][36256] = {name = "[q4]Abrazo de El Vacío Abisal", additional_info = "Hechizo de 15 seg\nHerramientas: Martillo de herrero\nComponentes:\nCamisa de anillas de El Vacío Abisal , Vórtice abisal (2)\n[q4]Abrazo de El Vacío Abisal\nSe liga al recogerlo\nPecho Malla\n1189 armadura\n+55 agilidad\n+56 aguante\n[q2]Aumenta tu índice de golpe + 26 p.\n[q2]Aumenta tu índice de golpe crítico + 35 p.\n\n[q0]Ranura roja\n[q0]Ranura amarilla\n[q0]Ranura azul\n[q0]Bono de ranura: + 4 agilidad\n\nDurabilidad 165 / 165\nNecesitas ser de nivel 70\n[q2]Uso: Te da inmunidad frente a los ataques físicos durante 6 s, pero no puedes atacar ni usar facultades físicas. (30 Min Reutilización)"}
MultiLanguageSpellData['mx'][36257] = {name = "[q4]Baluarte de los antiguos reyes", additional_info = "Hechizo de 15 seg\nHerramientas: Martillo de herrero\nComponentes:\nBaluarte de reyes , Vórtice abisal (2)\n[q4]Baluarte de los antiguos reyes\nSe liga al recogerlo\nPecho Placas\n1754 armadura\n+40 fuerza\n+56 aguante\n[q2]Aumenta tu índice de golpe + 25 p.\n[q2]Aumenta tu índice de golpe crítico + 41 p.\n\n[q0]Ranura azul\n[q0]Ranura amarilla\n[q0]Ranura amarilla\n[q0]Bono de ranura: + 4 golpe crítico\n\nDurabilidad 165 / 165\nNecesitas ser de nivel 70\n[q2]Uso: Aumenta temporalmente la salud 1736 p. y la fuerza 150 p. durante 15 s. (30 Min Reutilización)"}
MultiLanguageSpellData['mx'][36258] = {name = "[q4]Furia abrasadora", additional_info = "Hechizo de 15 seg\nHerramientas: Martillo de herrero\nComponentes:\nGuardia abrasadora , Vórtice abisal (5)\n[q4]Furia abrasadora\nSe liga al recogerlo\nUna mano Espada\n144 - 269 p. de daño Velocidad 1.60\n(129.06 p. de daño por segundo)\n+19 agilidad\n+28 aguante\n[q2]Aumenta tu índice de golpe + 18 p.\nDurabilidad 105 / 105\nNecesitas ser de nivel 70"}
MultiLanguageSpellData['mx'][36259] = {name = "[q4]Verdugo corazón de león", additional_info = "Hechizo de 15 seg\nHerramientas: Martillo de herrero\nComponentes:\nCampeón corazón de león , Vórtice abisal (5)\n[q4]Verdugo corazón de león\nSe liga al recogerlo\nÚnico-EquipadoDos manos Espada\n483 - 726 p. de daño Velocidad 3.60\n(167.92 p. de daño por segundo)\n+52 fuerza\n+44 agilidad\nDurabilidad 120 / 120\nNecesitas ser de nivel 70\n[q2]Equipar: Aumenta la probabilidad de resistir los efectos de miedo un 8%.\n[q2]Probabilidad al acertar: Aumenta la fuerza 115 p. durante 10 s."}
MultiLanguageSpellData['mx'][36260] = {name = "[q4]Filo despiadado de los planos", additional_info = "Hechizo de 15 seg\nHerramientas: Martillo de herrero\nComponentes:\nFilo bidimensional negro , Vórtice abisal (5)\n[q4]Filo despiadado de los planos\nSe liga al recogerlo\nUna mano Hacha\n244 - 454 p. de daño Velocidad 2.70\n(129.26 p. de daño por segundo)\n[q2]Aumenta tu índice de golpe crítico + 23 p.\n[q2]+ 48 de poder de ataque\nDurabilidad 105 / 105\nNecesitas ser de nivel 70"}
