MultiLanguageSpellData['mx'][53549] = {name = "Toque helado", additional_info = "Alcance de 20 m\nInstante\n[q]Inflige de 86 a 92 p. de daño de Escarcha modificado por el poder de ataque y reduce las velocidades de lanzamiento, ataque cuerpo a cuerpo y ataque a distancia un 86 to 92% durante hasta cancelación."}
MultiLanguageSpellData['mx'][53550] = {name = "Helada mental", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\n[q]Golpea la mente del objetivo con frío, inflige 100 p. de daño de Escarcha modificados por el poder de ataque e interrumpe el lanzamiento de hechizos mientras que también evita que se lance ningún hechizo de esa escuela durante 4 s."}
MultiLanguageSpellData['mx'][53551] = {name = "Limpieza Sagrada", additional_info = "[q]Tu hechizo Limpiar ahora también disipa efectos mágicos.\n[q]Modifies Effect #3's Value +100:\nLimpiar"}
MultiLanguageSpellData['mx'][53563] = {name = "Señal de la Luz", additional_info = "Alcance de 60 m\n{Instante} {3 seg de reutilización}\n[q]El objetivo se convierte en una Señal de la Luz para todos los miembros del grupo o banda en un radio de 60 m.\n\n Solo un objetivo puede ser la Señal de la Luz a la vez.\n\nSeñal de la Luz\n Tu Luz Sagrada también sanará a la señal un 100% de la cantidad sanada. Tu Radiancia Sagrada, Luz del alba, Martillo de la Luz y Prisma Sagrado sanarán un 15% de la cantidad sanada. El resto de sanaciones sanarán un 50% de la cantidad sanada."}
MultiLanguageSpellData['mx'][53570] = {name = "Frío hambriento", additional_info = "Alcance de 10 m\nInstante\n[q]Desata todo el poder rúnico disponible para eliminar de repente todo el calor de la tierra que rodea al caballero de la Muerte. Los enemigos que se encuentren en un radio de 10 m quedan atrapados en hielo, impidiendo que puedan realizar ninguna acción durante 1 s por cada 5 p. de poder rúnico. Se considera que los enemigos están congelados, pero cualquier daño romperá el hielo."}
MultiLanguageSpellData['mx'][53576] = {name = "Infusión de Luz", additional_info = "[q]Los efectos críticos de tu Choque Sagrado reducen 1.50 s el tiempo de lanzamiento de tu siguiente Luz Sagrada, Luz divina o Radiancia Sagrada."}
MultiLanguageSpellData['mx'][53592] = {name = "Custodiado por la Luz", additional_info = "[q]Aumenta un 25% tu aguante total y un 10% tu probabilidad de bloqueo.\n\n Reduce un 6% la probabilidad de que recibas un golpe crítico con ataques cuerpo a cuerpo.\n\n Palabra de gloria ya no activa el tiempo de reutilización global.\n\n Ahora tu poder con hechizos equivale a un 50% de tu poder de ataque y ya no te beneficias de otras fuentes de poder con hechizos.\n\n Otorga un 15% de tu maná máximo cada 2 s.\n(Probabilidad de que accione: 10%)"}
MultiLanguageSpellData['mx'][53595] = {name = "Martillo del honrado", additional_info = "{3% del maná base} {Alcance de ataques cuerpo a cuerpo}\n{Instante} {4.5 seg de reutilización}\nRequiere Arma cuerpo a cuerpo\n[q]Da un martillazo al objetivo actual que inflige un 20 % de daño con arma, lo que causa una ola de Luz que golpea a todos los objetivos en un radio de 8 m, inflige un 35 % de daño con arma Sagrado y aplica el efecto Golpes debilitados. Otorga una carga de Poder Sagrado.\n\n Golpes debilitados\n Desmoraliza al objetivo, lo que reduce el daño físico que inflige un 10% durante 30 s."}
MultiLanguageSpellData['mx'][53599] = {name = "Invocar dardo Anub'ar", additional_info = nil}
MultiLanguageSpellData['mx'][53600] = {name = "Escudo del honrado", additional_info = "3 Poder Sagrado Alcance de ataques cuerpo a cuerpo\n{Hechizo instantáneo} {1.5 seg de reutilización}\n[q]Sacude al instante a tu objetivo con tu escudo, lo que inflige 836 p. de daño Sagrado, reduce un (25 *- 1 ; Min 30, Max 80)% el daño físico que recibes durante 3 s y provoca Bastión de gloria.\n\nBastión de gloria\nAumenta un 10% la potencia de tu [ Llama eterna / Palabra de gloria] cuando la utilizas para sanarte a ti mismo. [ Sanación desinteresada : Sanación desinteresada también aumenta la sanación de Destello de Luz sobre ti mismo un 20% por acumulación ] Se acumula hasta 5 veces."}
MultiLanguageSpellData['mx'][53602] = {name = "Dardo", additional_info = "Rango ilimitado\nInstante\n[q]Lanza un rápido dardo al enemigo, inflige 750 p. de daño cada 3 s. Dura 12 s."}
