MultiLanguageSpellData['mx'][55642] = {name = "Bordado de tejido de luz", additional_info = "Hechizo de 4 seg\nRequiere Capa\nComponentes:\nHilo de eternio\n[q]Esta receta mejora automáticamente cuando alcanzas 500 p. de habilidad en sastrería.\n\n Borda un sutil diseño de luz en tu capa, lo que te da una probabilidad de aumentar tu intelecto 2950 p. durante 15 s cuando lanzas un hechizo.\n\n Bordar tu capa provocará que se ligue a ti y requiere que la profesión de sastrería esté activa."}
MultiLanguageSpellData['mx'][55643] = {name = "Regurgitar", additional_info = "Alcance de ataques cuerpo a cuerpo\nHechizo de 1.5 seg 1 min de reutilización\n[q]Inflige 2400 p. de daño de Naturaleza a un enemigo cada 1 s. También drena 240 p. de maná cada 1 s."}
