MultiLanguageSpellData['mx'][56460] = {name = "Bomba de fragmentación de cobalto", additional_info = "Hechizo de 2 seg\nHerramientas: Llave de tuerca arcoluz , Microajustador giromático\nComponentes:\nPuñado de tornillos de cobalto (2), Activador de explosivo volátil\n(3)\nRequiereIngeniería\n(330)\n[q2]Uso: Inflige ( 75 * 10) - ( 100 * 10) p. de daño de Fuego e incapacita a los objetivos en un radio de 3 m durante 3 s. Cualquier daño anulará el efecto. (1 Min Reutilización)"}
MultiLanguageSpellData['mx'][56461] = {name = "Piqueta afilada", additional_info = "Hechizo de 2 seg\nHerramientas: Martillo de herrero\nComponentes:\nBarra de cobalto (5)\nPiqueta con hojas\n[q]\"Se puede usar como pico de minería o como cuchillo desollador.\""}
MultiLanguageSpellData['mx'][56462] = {name = "Navaja gnómica", additional_info = "Hechizo de 2 seg\nHerramientas: Martillo de herrero\nComponentes:\nBarra de saronita (10), Cuchillo para desollar , Pico de minero , Martillo de herrero\n[q2]Uso: Un ingeniero con al menos 350 p. de habilidad puede sobrecargar la batería de la navaja para intentar resucitar con una descarga a un aliado muerto. No se puede usar en combate. (30 Min Reutilización)\n[q2]+10 minería\n +10 herboristería\n +10 desuello\n[q]\"Incluye microajustador giromático, llave de tuerca arcoluz, rascanarices, martillo de herrería, rascaespaldas y dispositivo giratorio.\""}
MultiLanguageSpellData['mx'][56463] = {name = "Señuelo explosivo", additional_info = "Hechizo de 2 seg\nHerramientas: Llave de tuerca arcoluz , Microajustador giromático\nComponentes:\nTela de tejido de Escarcha , Activador de explosivo volátil (3)\n(5)\nRequiereIngeniería\n(350)\n[q2]Uso: Invoca un señuelo que explota al ser atacado, tritura al enemigo y le inflige 1440 to 2160 p. de daño físico. Dura 3 min o hasta que explota. (2 Min Reutilización)\n[q]\"Etiqueta de aviso: Puede explotar antes de tiempo si se somete a un impulso electromagnético.\""}
MultiLanguageSpellData['mx'][56464] = {name = "Condensador sobrecargado", additional_info = "Hechizo de 2 seg\nHerramientas: Martillo de herrero\nComponentes:\nBarra de cobalto (4), Tierra cristalizada"}
MultiLanguageSpellData['mx'][56465] = {name = "[q3]Gafas de nieve mecanizadas", additional_info = "Hechizo de 2 seg\nHerramientas: Martillo de herrero\nComponentes:\nBarra de saronita (8), Cuero boreal (2), Sombra eterna\n[q3]Gafas de nieve mecanizadas\nSe liga al equiparlo\nCabeza Tela\n581 armadura\n[q2]<Encantamiento aleatorio>\nDurabilidad 85 / 85\nRequiereIngeniería\n(400)\n[q2]Equipar: Protegido del frío. Tu resistencia a la Escarcha aumenta 20 p."}
MultiLanguageSpellData['mx'][56466] = {name = "[q3]Propulsor sónico", additional_info = "Hechizo de 10 seg\nHerramientas: Martillo de herrero\nComponentes:\nTubo de acero gélido reforzado (2), Condensador sobrecargado (4), Puñado de tornillos de cobalto (2)\n[q3]Propulsor sónico\nSe liga al equiparlo\nAbalorio\n+81 aguante\nRequiereIngeniería\n(390)\n[q2]Equipar: El ruido que produce el combate cuerpo a cuerpo a veces provoca Conciencia sónica, que aumenta tu poder de ataque 498 p. durante 10 s. Este efecto solo puede darse una vez cada minuto. (Probabilidad de que accione: 35%, 50s de reutilización)"}
MultiLanguageSpellData['mx'][56467] = {name = "[q3]Máquina de ruido", additional_info = "Hechizo de 10 seg\nHerramientas: Martillo de herrero\nComponentes:\nTubo de acero gélido reforzado (2), Condensador sobrecargado (2), Puñado de tornillos de cobalto (8)\n[q3]Máquina de ruido\nSe liga al equiparlo\nAbalorio\n+54 intelecto\nRequiereIngeniería\n(390)\n[q2]Equipar: Los ataques cuerpo a cuerpo contra ti tienen la posibilidad de invocar un Escudo sónico que absorbe 1273 p. de daño. Este efecto solo puede tener lugar una vez por minuto. (Probabilidad de que accione: 50%, 50s de reutilización)"}
MultiLanguageSpellData['mx'][56468] = {name = "Caja de bombas", additional_info = "Hechizo de 2 seg\nHerramientas: Martillo de herrero , Microajustador giromático\nComponentes:\nBarra de saronita (5), Activador de explosivo volátil\n[q]\"Contiene bombas de saronita. Muchas.\"\n[q2]<Click derecho para abrir>"}
MultiLanguageSpellData['mx'][56469] = {name = "[q3]Generador de relámpagos gnómico", additional_info = "Hechizo de 10 seg\nHerramientas: Martillo de herrero\nComponentes:\nBarra de titanio (2), Barra de saronita (8), Agua eterna (2), Aire eterno (2)\n[q3]Generador de relámpagos gnómico\nSe liga al recogerlo\nAbalorio\n[q2]Aumenta tu índice de golpe crítico + 84 p.\nRequiereIngeniería\n(425)\n[q2]Uso: Genera una descarga de relámpagos que golpea a un enemigo y le inflige 1953 p. de daño de Naturaleza. Este aparato está construido entero con metal... (1 Min Reutilización)\n[q]\"¡Es seguro!\""}
MultiLanguageSpellData['mx'][56470] = {name = "[q3]Mira solar", additional_info = "Hechizo de 10 seg\nHerramientas: Martillo de herrero\nComponentes:\nTubo de acero gélido reforzado , Cristal de sol , Brillo del otoño\n[q3]Mira solar\nNecesitas ser de nivel 70\n[q2]Uso: Añade una mira permanente a un arco o arma de fuego que aumenta tu celeridad a distancia 40 p.\n\n Al añadir la mira, el arma a distancia se liga."}
