MultiLanguageSpellData['mx'][56472] = {name = "[q3]MOL-E", additional_info = "Hechizo de 10 seg\nHerramientas: Martillo de herrero\nComponentes:\nBarra de saronita (8), Aire eterno (8)\n[q3]MOL-E\nSe liga al usarlo\nJuguete\nRequiereIngeniería\n(425)\n[q2]Uso: Crea un buzón portátil durante 10 min. MOL-E no se destruye después de usarla. (1 Hora Reutilización)\n[q]\"Maquinaria Organizadora de Libros Enormes.\""}
