MultiLanguageSpellData['mx'][56943] = {name = "Glifo de Regeneración frenética", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta etérea (3)\n[q9]Glifo Sublime\nClases: Druida\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nDurante 6 s después de activar Regeneración frenética, los efectos de sanación sobre ti son un 40% más potentes. Sin embargo, tu Regeneración frenética ahora cuesta 50 p. de ira y ya no transforma ira en salud."}
MultiLanguageSpellData['mx'][56944] = {name = "Glifo de Augurios", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta del mar (3)\n[q9]Glifo Sublime\nClases: Druida\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nCuando no estás en estado de Eclipse, las siguientes facultades otorgan 10 p. de energía solar o lunar: Raíces enredadoras, Ciclón, Fuego feérico, Enjambre feérico, Enredo masivo, Tifón, Rugido desorientador, Vórtice de Ursol y Azote poderoso."}
MultiLanguageSpellData['mx'][56945] = {name = "Glifo de Toque de sanación", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta de león (3)\n[q9]Glifo Sublime\nClases: Druida\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nCuando lanzas Toque de sanación, el tiempo de reutilización de Presteza de la Naturaleza se reduce 3 s."}
MultiLanguageSpellData['mx'][56946] = {name = "Glifo de Huracán", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta del mar (3)\n[q9]Glifo Sublime\nClases: Druida\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nTus facultades Huracán y Tormenta astral ahora también reducen la velocidad de movimiento de sus víctimas un 50%."}
MultiLanguageSpellData['mx'][56947] = {name = "Glifo de Estimular", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta del mar (3)\n[q9]Glifo Sublime\nClases: Druida\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nCuando Estimular se lanza sobre un objetivo diferente al taumaturgo, el taumaturgo y el objetivo se beneficiarán, pero con un efecto reducido un 40%."}
MultiLanguageSpellData['mx'][56948] = {name = "Glifo de La orca", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta de fuego de jade (3)\n[q9]Glifo Menor\nClases: Druida\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nTu Forma acuática ahora tiene el aspecto de una orca."}
MultiLanguageSpellData['mx'][56949] = {name = "Glifo de Floración", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta del mar (3)\n[q9]Glifo Sublime\nClases: Druida\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nAhora el efecto Floración es provocado por tu Champiñón salvaje, en lugar de por Alivio presto, siempre que el Champiñón salvaje esté activo. Además, aumenta la sanación realizada de Alivio presto un 20%."}
MultiLanguageSpellData['mx'][56950] = {name = "Glifo de El venado", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta del mar (3)\n[q9]Glifo Menor\nClases: Druida\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nAhora tu Forma de viaje puede usarse de montura para los miembros del grupo. Este glifo está desactivado mientras Glifo de El guepardo está activo."}
MultiLanguageSpellData['mx'][56951] = {name = "Glifo de Salvajismo", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta de león (3)\n[q9]Glifo Sublime\nClases: Druida\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nAhora se puede utilizar Rugido salvaje con 0 p. de combo, con una duración de 12 s."}
MultiLanguageSpellData['mx'][56952] = {name = "Glifo de Abalanzarse", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta etérea (3)\n[q9]Glifo Sublime\nClases: Druida\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nAumenta 8 m el alcance de tu Abalanzarse."}
MultiLanguageSpellData['mx'][56953] = {name = "Glifo de Renacer", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta de fuego de jade (3)\n[q9]Glifo Sublime\nClases: Druida\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nLos jugadores resucitados con Renacer vuelven a la vida con un 100% de salud."}
MultiLanguageSpellData['mx'][56954] = {name = "Glifo de Recrecimiento", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta del mar (3)\n[q9]Glifo Sublime\nClases: Druida\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nAumenta la probabilidad de golpe crítico de tu Recrecimiento un 40%, pero elimina el componente periódico del hechizo."}
MultiLanguageSpellData['mx'][56955] = {name = "Glifo de Rejuvenecimiento", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta de medianoche (3)\n[q9]Glifo Sublime\nClases: Druida\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nCuando Rejuvenecimiento está activo en tres o más objetivos, el tiempo de lanzamiento de tu hechizo Nutrir se reduce un 30%."}
MultiLanguageSpellData['mx'][56956] = {name = "Glifo de Acechar", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta celestial (3)\n[q9]Glifo Sublime\nClases: Druida\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nReduce un 100% la penalización de movimiento de Acechar."}
MultiLanguageSpellData['mx'][56957] = {name = "Glifo de Triturar", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta fulgurante (3)\n[q9]Glifo Sublime\nClases: Druida\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nCuando Rabia o Furia del tigre está activo, Triturar no tiene requisitos de posición."}
MultiLanguageSpellData['mx'][56959] = {name = "Glifo de Estrellas guiadas", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta celestial (3)\n[q9]Glifo Sublime\nClases: Druida\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nTu Lluvia de estrellas solo golpea a los objetivos afectados por tu Fuego lunar o Fuego solar."}
MultiLanguageSpellData['mx'][56960] = {name = "Glifo de Estampida", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta del mar (3)\n[q9]Glifo Sublime\nClases: Druida\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nAhora puedes lanzar Rugido de estampida sin estar en forma de oso o forma felina."}
MultiLanguageSpellData['mx'][56961] = {name = "Glifo de Magullar", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta de medianoche (3)\n[q9]Glifo Sublime\nClases: Druida\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nTu facultad Magullar ahora golpea a 1 objetivo adicional e inflige un 50% de daño."}
MultiLanguageSpellData['mx'][56963] = {name = "Glifo de Trabazón con la Naturaleza", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta de medianoche (3)\n[q9]Glifo Sublime\nClases: Druida\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nReduce el tiempo de reutilización de Trabazón con la Naturaleza 45 s."}
MultiLanguageSpellData['mx'][56965] = {name = "Glifo de Estrellas", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta del mar (3)\n[q9]Glifo Menor\nClases: Druida\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nTu facultad Forma de lechúcico lunar ahora se muestra como Forma astral. Otorga los mismos beneficios, pero el aspecto cambia a una versión astral mejorada de tu forma humanoide normal."}
MultiLanguageSpellData['mx'][56966] = {name = "Aviso de límites", additional_info = "Rango ilimitado\nInstante\n[q]Este vehículo ha salido de sus límites. ¡Regresa al campo de batalla inmediatamente!"}
MultiLanguageSpellData['mx'][56969] = {name = "Explosión Arcana", additional_info = "Alcance de 30 m\nHechizo de 2.5 seg\n[q]Golpea al objetivo con energía, inflige 4375 to 5625 p. de daño Arcano. Cada vez que lances el hechizo Explosión Arcana, se reducirá el tiempo de lanzamiento de hechizos. El efecto se acumula hasta 5 veces y dura 8 s."}
MultiLanguageSpellData['mx'][56971] = {name = "Glifo de Maná suelto", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta de león (3)\n[q9]Glifo Menor\nClases: Mago\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nTu gema de maná ahora restaura maná durante 6 s en lugar de instantáneamente."}
MultiLanguageSpellData['mx'][56972] = {name = "Glifo de Deflagración Arcana", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta etérea (3)\n[q9]Glifo Sublime\nClases: Mago\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nAumenta el radio de tu Deflagración Arcana 5 m."}
