MultiLanguageSpellData['mx'][57033] = {name = "Glifo de Aura de devoción", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta etérea (3)\n[q9]Glifo Sublime\nClases: Paladín\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nAura de devoción ya no afecta a los miembros del grupo o banda, pero el tiempo de reutilización se reduce 60 s."}
