MultiLanguageSpellData['mx'][65790] = {name = "Contrahechizo", additional_info = "{9% del maná base} {Alcance de 30 m}\n{Instante} {24 seg de reutilización}\n[q]Contrarresta el lanzamiento de hechizos del enemigo, evitando que lance hechizos de esa escuela de magia durante 8 s. Genera una gran cantidad de amenaza."}
MultiLanguageSpellData['mx'][65791] = {name = "Explosión Arcana", additional_info = "{8% del maná base} {Alcance de 30 m}\nHechizo de 2.5 seg\n[q]Golpea al objetivo con energía, lo que inflige 12488 to 14512 p. de daño Arcano. Cada vez que lances el hechizo Explosión Arcana, el daño de todos tus hechizos Arcanos aumentará un 50% y el coste de maná de Explosión Arcana aumentará un 150%. El efecto se acumula hasta 4 veces y dura 10 s o hasta que se lance un hechizo que inflija daño Arcano, excepto Explosión Arcana."}
MultiLanguageSpellData['mx'][65792] = {name = "Nova de Escarcha", additional_info = "8% del maná base\n{Instante} {25 seg de reutilización}\n[q]Golpea a los enemigos situados cerca del taumaturgo, lo que inflige 365 to 415 p. de daño de Escarcha y los congela durante un máximo de 8 s. Cualquier daño infligido puede interrumpir su efecto."}
MultiLanguageSpellData['mx'][65793] = {name = "Traslación", additional_info = "21% del maná base\n{Instante} {15 seg de reutilización}\n[q]Teletransporta al taumaturgo 20 m hacia delante salvo si hay algún obstáculo y lo libera de sus ataduras y del aturdimiento."}
MultiLanguageSpellData['mx'][65794] = {name = "Bola de la luz pasiva", additional_info = nil}
MultiLanguageSpellData['mx'][65795] = {name = "Luz desatada", additional_info = "Rango ilimitado\nInstante\n[q]La Bola de la Luz libera su energía e inflige 14625 to 15375 p. de daño de la Luz a los enemigos en un radio de 6 m."}
MultiLanguageSpellData['mx'][65796] = {name = "Bola de la oscuridad pasiva", additional_info = nil}
MultiLanguageSpellData['mx'][65797] = {name = "Lluvia de estrellas", additional_info = "Alcance de 40 m\nInstante\n[q]Invoca un aluvión de estrellas que caen del cielo sobre todos los objetivos en un radio de 30 m del taumaturgo e infligen, cada una, 124 to 166 p. de daño Arcano a todos los enemigos en un radio de 5 m del objetivo enemigo. Dura 8 s."}
MultiLanguageSpellData['mx'][65798] = {name = "Lluvia de estrellas", additional_info = "Canalizado (Hechizo de 8 seg) 30 seg de reutilización\n[q]Invoca un aluvión de estrellas que caen del cielo sobre todos los objetivos en un radio de 30 m del taumaturgo e infligen, cada una, 124 to 166 p. de daño Arcano a todos los enemigos en un radio de 5 m del objetivo enemigo. Dura 8 s."}
MultiLanguageSpellData['mx'][65799] = {name = "Tromba Arcana", additional_info = "{18% del maná base} {Alcance de 30 m}\n{Instante} {3 seg de reutilización}\n[q]Lanza contra el objetivo enemigo varios misiles que le infligen 10450 to 11550 p. de daño Arcano."}
MultiLanguageSpellData['mx'][65800] = {name = "Deflagración Arcana", additional_info = "22% del maná base\nInstante\n[q]Provoca una explosión de magia Arcana alrededor del taumaturgo, lo que inflige 5280 to 5720 p. de daño Arcano a todos los objetivos en un radio de 10 m."}
MultiLanguageSpellData['mx'][65801] = {name = "Polimorfia", additional_info = "{7% del maná base} {Alcance de 30 m}\nHechizo de 1.5 seg 15 seg de reutilización\n[q]Transforma al enemigo en oveja y le obliga a deambular durante 10 s. Mientras deambula, la oveja no puede atacar ni lanzar hechizos. Si recibe daño volverá a su forma normal. Solo se puede aplicar polimorfia a 1 objetivo al mismo tiempo. Solo funciona con bestias, humanoides y alimañas."}
MultiLanguageSpellData['mx'][65802] = {name = "Bloque de hielo", additional_info = "15 p. de maná\n{Instante} {5 min de reutilización}\n[q]Te envuelve en un bloque de hielo que te protege de todos los ataques físicos y hechizos durante 5 s, pero durante ese tiempo no puedes moverte, atacar ni lanzar hechizos. También provoca Hipotermia, que te impide volver a lanzar Bloque de hielo durante 30 s."}
MultiLanguageSpellData['mx'][65803] = {name = "Aturdimiento de trituradora", additional_info = nil}
MultiLanguageSpellData['mx'][65804] = {name = "Plantar estandarte de la Horda", additional_info = "Alcance de 5 m\nInstante\n[q]¡Por la Horda!"}
MultiLanguageSpellData['mx'][65805] = {name = "Summon Ashenvale Archers 00", additional_info = nil}
MultiLanguageSpellData['mx'][65806] = {name = "Tiro con arco de arquera de Vallefresno", additional_info = nil}
MultiLanguageSpellData['mx'][65807] = {name = "Descarga de Escarcha", additional_info = "{13% del maná base} {Alcance de 30 m}\nHechizo de 2.5 seg\n[q]Lanza una descarga de Escarcha al enemigo que inflige 11563 to 13437 p. de daño de Escarcha y reduce su velocidad de movimiento un 40% durante 9 s."}
MultiLanguageSpellData['mx'][65808] = {name = "Oscuridad desatada", additional_info = "Rango ilimitado\nInstante\n[q]La oscuridad concentrada libera su energía e inflige 14625 to 15375 p. de daño de la oscuridad a los enemigos en un radio de 6 m."}
MultiLanguageSpellData['mx'][65809] = {name = "Miedo", additional_info = "{12% del maná base} {Alcance de 20 m}\nHechizo de 1.5 seg 8 seg de reutilización\n[q]Provoca miedo en el enemigo y hace que huya durante un máximo de 10 s. El daño infligido puede interrumpir el efecto. Solo se puede asustar a 1 objetivo cada vez."}
MultiLanguageSpellData['mx'][65810] = {name = "Corrupción", additional_info = "{14% del maná base} {Alcance de 30 m}\nInstante\n[q]Corrompe al objetivo e inflige 30000 p. de daño de las Sombras durante 18 s."}
MultiLanguageSpellData['mx'][65811] = {name = "Efecto 2 de esencia de la luz", additional_info = nil}
MultiLanguageSpellData['mx'][65812] = {name = "Aflicción inestable", additional_info = "{15% del maná base} {Alcance de 30 m}\nHechizo de 1.5 seg 15 seg de reutilización\n[q]La energía de las Sombras destruye poco a poco al objetivo e inflige 23125 to 26875 p. de daño durante 15 s. Además, si se disipa tu hechizo Aflicción inestable, el que lo haya disipado recibirá 13875 to 16125 p. de daño de las Sombras y quedará silenciado durante 4 s."}
MultiLanguageSpellData['mx'][65813] = {name = "Aflicción inestable", additional_info = "Rango ilimitado\nInstante\n[q]Al disipar Aflicción inestable, el disipador recibe 13875 to 16125 p. de daño de las Sombras y es silenciado durante 5 s."}
MultiLanguageSpellData['mx'][65814] = {name = "Maldición de agonía", additional_info = "{10% del maná base} {Alcance de 30 m}\nInstante\n[q]Lanza sobre el objetivo una Maldición de agonía, lo que inflige 42000 p. de daño de las Sombras durante 24 s. El daño se inflige despacio al principio y aumenta progresivamente a medida que la maldición alcanza su duración completa. Un brujo solo puede tener una maldición activa a la vez sobre un mismo objetivo."}
MultiLanguageSpellData['mx'][65815] = {name = "Maldición de agotamiento", additional_info = "{6% del maná base} {Alcance de 30 m}\nInstante\n[q]Reduce la velocidad de movimiento del objetivo un 50% durante 12 s. Cada brujo solo puede tener una maldición activa sobre cada objetivo."}
MultiLanguageSpellData['mx'][65816] = {name = "Llamas infernales", additional_info = "64% del maná base\nCanalizado (Hechizo de 15 seg)\n[q]Prende el área que rodea al taumaturgo, infligiéndose 1500 p. de daño de Fuego a sí mismo y 9000 p. de daño de Fuego a todos los demás enemigos cercanos cada 1 s. Dura 15 s."}
MultiLanguageSpellData['mx'][65817] = {name = "Efecto de Llamas infernales", additional_info = "Instante\n[q]Prende el área que rodea al taumaturgo, infligiéndose 1500 p. de daño de Fuego a sí mismo y 9000 p. de daño de Fuego a todos los demás enemigos cercanos cada 1 s. Dura 15 s."}
MultiLanguageSpellData['mx'][65819] = {name = "Dolor abrasador", additional_info = "{8% del maná base} {Alcance de 30 m}\nHechizo de 1.5 seg\n[q]Inflige un dolor abrasador al objetivo enemigo infligiendo 5490 to 6510 p. de daño de Fuego."}
MultiLanguageSpellData['mx'][65820] = {name = "Espiral de la muerte", additional_info = "{23% del maná base} {Alcance de 30 m}\n{Instante} {2 min de reutilización}\n[q]Provoca que un objetivo enemigo corra horrorizado durante 3 s e inflige 9425 to 10575 p. de daño de las Sombras. El taumaturgo transforma en salud el 500% del daño infligido."}
MultiLanguageSpellData['mx'][65821] = {name = "Descarga de las Sombras", additional_info = "{17% del maná base} {Alcance de 30 m}\nHechizo de 2.5 seg\n[q]Lanza una descarga de las Sombras al enemigo, lo que le inflige 11813 to 13187 p. de daño de las Sombras."}
