MultiLanguageSpellData['mx'][65855] = {name = "Enjambre de insectos", additional_info = "{8% del maná base} {Alcance de 30 m}\nInstante\n[q]Rodea al objetivo enemigo de insectos, lo que reduce su probabilidad de golpear con ataques cuerpo a cuerpo y a distancia un 3%, e inflige 22200 to 25800 p. de daño de Naturaleza durante 12 s."}
MultiLanguageSpellData['mx'][65856] = {name = "Fuego lunar", additional_info = "{21% del maná base} {Alcance de 30 m}\n{Instante} {5 seg de reutilización}\n[q]Quema al enemigo, inflige 4140 to 4860 p. de daño Arcano y 7000 p. de daño Arcano extra durante 12 s."}
MultiLanguageSpellData['mx'][65857] = {name = "Raíces enredadoras", additional_info = "{7% del maná base} {Alcance de 30 m}\nHechizo de 1.5 seg 10 seg de reutilización\n[q]Enraíza al objetivo en el sitio e inflige 1576.7 to 1756.7 p. de daño de Naturaleza durante 10 s. El daño infligido puede interrumpir el efecto."}
MultiLanguageSpellData['mx'][65858] = {name = "Escudo de la luz", additional_info = "Instante\n[q]Un escudo de la luz que protege a la hermana del peligro y absorbe 1200000 p. de daño y evita la interrupción de hechizos durante 16 s."}
MultiLanguageSpellData['mx'][65859] = {name = "Ciclón", additional_info = "{8% del maná base} {Alcance de 20 m}\nHechizo de 1.5 seg 6 seg de reutilización\n[q]Lanza al objetivo enemigo por los aires, lo que evita que pueda realizar ninguna acción, pero lo hace invulnerable durante 6 s. Ciclón solo puede afectar a un objetivo a la vez."}
MultiLanguageSpellData['mx'][65860] = {name = "Piel de corteza", additional_info = "{Instante} {1 min de reutilización}\n[q]La piel del druida se endurece como la corteza de un árbol. Todo el daño recibido se reduce un 40%. Se puede usar mientras se está aturdido, congelado, incapacitado, asustado o dormido. Se puede usar bajo todas las formas. Dura 12 s."}
MultiLanguageSpellData['mx'][65861] = {name = "Fuerza de la Naturaleza", additional_info = "{12% del maná base} {Alcance de 30 m}\n{Instante} {3 min de reutilización}\n[q]Invoca a 3 antárboles que atacan a los objetivos enemigos durante 30 s."}
MultiLanguageSpellData['mx'][65862] = {name = "Cólera", additional_info = "{11% del maná base} {Alcance de 30 m}\nHechizo de 1.5 seg\n[q]Inflige 8460 to 9540 p. de daño de Naturaleza al objetivo."}
MultiLanguageSpellData['mx'][65863] = {name = "Fuego feérico", additional_info = "{8% del maná base} {Alcance de 30 m}\nInstante\n[q]Reduce la armadura del objetivo un 15% durante 40 s. Mientras dura su efecto, el objetivo no puede utilizar el sigilo ni hacerse invisible."}
MultiLanguageSpellData['mx'][65864] = {name = "En picado", additional_info = "30 p. de enfoque\n{Hechizo instantáneo} {32 seg de reutilización}\n[q]Aumenta tu velocidad de movimiento un 80% durante 5 s."}
