MultiLanguageSpellData['mx'][65866] = {name = "Disparo explosivo", additional_info = "{7% del maná base} {Alcance de 35 m}\n6 seg de reutilización\nRequiere Arma a distancia\n[q]Lanzas una carga explosiva al objetivo, que inflige 4533 to 5467 p. de daño de Fuego. La carga golpeará al objetivo cada segundo durante 2 s adicionales."}
MultiLanguageSpellData['mx'][65867] = {name = "Disparo firme", additional_info = "{5% del maná base} {Alcance de 35 m}\nHechizo de 1.5 seg 3 seg de reutilización\nRequiere Arma a distancia\n[q]Un disparo firme que provoca daño con arma a un objetivo."}
