MultiLanguageSpellData['mx'][65877] = {name = "Picadura de dracoleón", additional_info = "{8% del maná base} {Alcance de 35 m}\n1 min de reutilización\nRequiere Arma a distancia\n[q]Un disparo punzante que duerme al objetivo durante 8 s. Cualquier daño infligido con posterioridad anulará su efecto. Cuando el objetivo se despierta, la picadura inflige 2.6 p. de daño de Naturaleza durante 8 s. Un cazador solo puede tener una picadura activa a la vez sobre un mismo objetivo."}
MultiLanguageSpellData['mx'][65878] = {name = "Picadura de dracoleón", additional_info = "Rango ilimitado\nInstante\n[q]Un disparo punzante que duerme al objetivo durante 6 s. Cualquier daño infligido con posterioridad anulará su efecto. Cuando el objetivo se despierta, la picadura provoca 6000 p. de daño de Naturaleza durante 6 s. Un cazador solo puede tener una picadura activa a la vez sobre un mismo objetivo."}
MultiLanguageSpellData['mx'][65879] = {name = "Poder de las Gemelas", additional_info = "Instante\n[q]El poder compartido de las Gemelas aumenta el daño físico infligido un 20% y permite a las Gemelas la doble empuñadura durante 15 s.\n(500ms de reutilización)"}
