MultiLanguageSpellData['mx'][73680] = {name = "Desatar elementos", additional_info = "{8.2% del maná base} {Alcance de 40 m}\n{Instante} {15 seg de reutilización}\n[q]Centra la fuerza elemental imbuida en el armamento del chamán, con efectos concentrados según el encantamiento liberado. [ Doble empuñadura : Si el arma tiene los dos encantamientos, solo se liberará uno ]\n Consulta las descripciones de cada hechizo de imbuir arma para ver los detalles relacionados con los efectos de desatar cada uno."}
MultiLanguageSpellData['mx'][73681] = {name = "Desatar viento", additional_info = "Alcance de 100 m\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Desata el encantamiento Viento furioso sobre el arma del chamán, lo que inflige un 90% de daño con arma al objetivo enemigo y aumenta un 50% la velocidad de ataque cuerpo a cuerpo del chamán durante los siguientes 6 golpes o hasta que hayan pasado 12 s."}
MultiLanguageSpellData['mx'][73682] = {name = "Desatar Escarcha", additional_info = "Alcance de 100 m\nInstante\n[q]Desata el encantamiento Estigma de Escarcha sobre el arma del chamán, que inflige 969 p. de daño de Escarcha a un objetivo enemigo y reduce su velocidad de movimiento un 50 % durante 5 s. Ve aumentada su eficacia si el objetivo ya está afectado por un efecto de Escarcha de ralentización de movimiento."}
MultiLanguageSpellData['mx'][73683] = {name = "Desatar llama", additional_info = "Alcance de 100 m\nInstante\n[q]Desata el encantamiento de Lengua de Fuego sobre el arma del chamán, lo que inflige 1241 p. de daño de Fuego al objetivo enemigo y aumenta un 30 % el daño infligido por el siguiente hechizo de Fuego del chamán."}
MultiLanguageSpellData['mx'][73684] = {name = "Desatar tierra", additional_info = "Alcance de 100 m\n{Instante} {15 seg de reutilización}\n[q]Desata el encantamiento Muerdepiedras sobre el arma del chamán, que obliga al objetivo enemigo a atacar al chamán y aumenta la amenaza que generas contra el objetivo un 200% durante 5 s."}
MultiLanguageSpellData['mx'][73685] = {name = "Desatar vida", additional_info = "Alcance de 100 m\n{Instante} {15 seg de reutilización}\n[q]Desata el encantamiento de Vida terrestre sobre el arma del chamán, que sana a un objetivo amistoso 3154 p. y aumenta el efecto de la siguiente sanación directa o Lluvia de sanación del chamán un 30 %."}
