MultiLanguageSpellData['mx'][79856] = {name = "Fogonazo", additional_info = "{35 p. de maná} {Alcance de 30 m}\nHechizo de 3 seg\n[q]Invoca una columna de llamas que quema a todos los enemigos del área seleccionada e inflige daño extra cada 2 s durante 8 s."}
MultiLanguageSpellData['mx'][79857] = {name = "Ola explosiva", additional_info = "35 p. de maná\nHechizo de 3 seg\n[q]Desata una ola de llamas que inflige daño de Fuego a los enemigos cercanos y reduce su velocidad de movimiento durante 6 s."}
