MultiLanguageSpellData['mx'][79863] = {name = "Hemorragia", additional_info = "{40 p. de energía} {Alcance de ataques cuerpo a cuerpo}\nInstante\n[q]Inflige daño con arma y aumenta el daño físico recibido por un enemigo un 20% durante 10 s."}
MultiLanguageSpellData['mx'][79864] = {name = "Paso de las Sombras", additional_info = "{20 p. de energía} {Alcance de 40 m}\n{Instante} {30 seg de reutilización}\n[q]Intenta dar un paso en las sombras y reaparecer detrás de tu enemigo."}
MultiLanguageSpellData['mx'][79865] = {name = "Armadura de Escarcha", additional_info = "{Instante} {10 seg de reutilización}\n[q]Reviste al taumaturgo con una capa de Escarcha que dura 30 min. El hielo espeso aumenta la armadura, ralentiza el movimiento de los atacantes cuerpo a cuerpo y aumenta el tiempo entre los ataques."}
MultiLanguageSpellData['mx'][79866] = {name = "Lanzamiento mortal", additional_info = "{20 p. de energía} {Alcance de 30 m}\nInstante\n[q]Lanza una daga al enemigo y le inflige un 24 to 29% de daño con arma. También interrumpe el lanzamiento de hechizos y evita que se pueda lanzar cualquier hechizo de esa misma escuela durante 3 s."}
MultiLanguageSpellData['mx'][79867] = {name = "Phase 20 to Normal", additional_info = nil}
MultiLanguageSpellData['mx'][79868] = {name = "Explosión Arcana", additional_info = "{7% del maná base} {Alcance de 30 m}\nHechizo de 2.5 seg\n[q]Golpea al objetivo con energía, lo que inflige daño Arcano. Cada vez que lances Explosión Arcana, el daño de todos tus hechizos Arcanos aumentará un 50% y el coste de maná de Explosión Arcana aumentará un 150%. El efecto se acumula hasta 4 veces y dura 10 s o hasta que se lance un hechizo que inflija daño Arcano, excepto Explosión Arcana."}
MultiLanguageSpellData['mx'][79869] = {name = "Misiles Arcanos", additional_info = "{35 p. de maná} {Alcance de 30 m}\nCanalizado (Hechizo de 5 seg)\n[q]Lanza misiles mágicos a un enemigo y le inflige daño Arcano cada segundo durante 5 s."}
MultiLanguageSpellData['mx'][79870] = {name = "Carga feral", additional_info = "{5 p. de ira} {Alcance de 8 - 25 m}\n{Hechizo instantáneo} {15 seg de reutilización}\n[q]Provoca que cargues contra un enemigo, lo que lo inmoviliza e interrumpe el lanzamiento de todos los hechizos durante hasta cancelación."}
MultiLanguageSpellData['mx'][79871] = {name = "Temeridad", additional_info = "Instante\n[q]Inmune a todos los efectos de miedo.\n Todos los ataques asestan golpes críticos.\n Armadura reducida un 35%."}
MultiLanguageSpellData['mx'][79872] = {name = "Ola de choque", additional_info = "Hechizo de 2 seg 20 seg de reutilización\n[q]Envía una ola de fuerza frente al guerrero, lo que inflige daño y aturde a los objetivos enemigos en un radio de 10 m en un cono frontal durante 4 s."}
MultiLanguageSpellData['mx'][79875] = {name = "¡Machaque Ongolongo!", additional_info = "Alcance de 10 m\nHechizo de 0.5 seg\n[q]Golpea al objetivo hacia atrás."}
MultiLanguageSpellData['mx'][79876] = {name = "Sed de sangre", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\n[q]Sana al taumaturgo un 1% de su salud máxima."}
MultiLanguageSpellData['mx'][79877] = {name = "Sed de sangre", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\n[q]Ataca instantáneamente al objetivo, lo que le inflige un 120% de daño con arma normal. Además, los ataques cuerpo a cuerpo con éxito restaurarán un 1% de la salud máxima. Este efecto dura 10 s."}
MultiLanguageSpellData['mx'][79878] = {name = "Sed de sangre", additional_info = "Alcance de ataques cuerpo a cuerpo\n{Instante} {10 seg de reutilización}\nRequiere Arma cuerpo a cuerpo\n[q]Ataca instantáneamente al objetivo infligiéndole un 120% de daño con arma normal. Además, los ataques cuerpo a cuerpo que alcancen al objetivo restaurarán un 1% de salud máxima. Este efecto dura 10 s."}
MultiLanguageSpellData['mx'][79879] = {name = "Descarga eléctrica", additional_info = "Rango ilimitado\nInstante\n[q]Inflige 43875 to 46125 p. de daño de Naturaleza a un máximo de 3 enemigos en un radio de 8 m."}
MultiLanguageSpellData['mx'][79880] = {name = "Ralentizar", additional_info = "{25 p. de maná} {Alcance de 30 m}\nInstante\n[q]Aumenta el tiempo entre los ataques de un enemigo un 25%, aumenta el tiempo de lanzamiento un 25% y ralentiza su velocidad de movimiento un 25% durante 6 s."}
MultiLanguageSpellData['mx'][79881] = {name = "Embate", additional_info = "Alcance de ataques cuerpo a cuerpo\nHechizo de 1.5 seg\n[q]Golpea al adversario, lo que inflige daño con arma más una cantidad extra."}
