MultiLanguageSpellData['mx'][79884] = {name = "Descarga de relámpagos", additional_info = "{15 p. de maná} {Alcance de 40 m}\nHechizo de 3 seg\n[q]Golpea a un objetivo con relámpagos, lo que le inflige daño de Naturaleza."}
