MultiLanguageSpellData['mx'][79955] = {name = "Lluvia de Fuego", additional_info = "{35 p. de maná} {Alcance de 30 m}\nCanalizado (Hechizo de 9 seg)\n[q]Invoca una lluvia de arrabio que quema a todos los enemigos del área seleccionada e inflige daño de Fuego cada 3 s durante 9 s."}
