MultiLanguageSpellData['mx'][79967] = {name = "Escudo Sagrado", additional_info = "10% del maná base\nInstante\n[q]Aumenta la probabilidad de bloquear un 30% durante 10 s e inflige daño Sagrado por cada ataque bloqueado mientras está activo. Cada bloqueo gasta una carga. 3 cargas."}
